def with_history_disabled(func):
    """Decorator to temporarily disable history saving for the prompt session buffer."""

    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        orig_buf_append = self.prompt_session.default_buffer.append_to_history
        self.prompt_session.default_buffer.append_to_history = lambda: None  # Replace with no-op

        try:
            return func(self, *args, **kwargs)
        except Exception:
            raise
        finally:
            self.prompt_session.default_buffer.append_to_history = orig_buf_append

    return wrapper

def _prepare_generation_inputs(
    self,
    input_ids: torch.Tensor,
    past_key_values: Optional[Tuple[Tuple[torch.FloatTensor]]] = None,
    attention_mask: Optional[torch.Tensor] = None,
    inputs_embeds: Optional[torch.Tensor] = None,
    cache_position: Optional[torch.Tensor] = None,
    position_ids: Optional[torch.Tensor] = None,
    use_cache=True,
) -> _GenerationInputs:
    # With static cache, the `past_key_values` is None
    # TODO joao: standardize interface for the different Cache classes and remove of this if
    has_static_cache = False
    if past_key_values is None:
        if hasattr(self.gpt.layers[0], "self_attn"):
            past_key_values = getattr(
                self.gpt.layers[0].self_attn, "past_key_value", None
            )
        has_static_cache = past_key_values is not None

    past_length = 0
    if past_key_values is not None:
        if isinstance(past_key_values, Cache):
            past_length = (
                int(cache_position[0])
                if cache_position is not None
                else past_key_values.get_seq_length()
            )
            try:
                max_cache_length = past_key_values.get_max_cache_shape()
            except:
                max_cache_length = (
                    past_key_values.get_max_length()
                )  # deprecated in transformers 4.48
            cache_length = (
                past_length
                if max_cache_length is None
                else min(max_cache_length, past_length)
            )
        # TODO joao: remove this `else` after `generate` prioritizes `Cache` objects
        else:
            cache_length = past_length = past_key_values[0][0].shape[2]
            max_cache_length = None

        # Keep only the unprocessed tokens:
        # 1 - If the length of the attention_mask exceeds the length of input_ids, then we are in a setting where
        # some of the inputs are exclusively passed as part of the cache (e.g. when passing input_embeds as
        # input)
        if (
            attention_mask is not None
            and attention_mask.shape[1] > input_ids.shape[1]
        ):
            start = attention_mask.shape[1] - past_length
            input_ids = input_ids.narrow(1, -start, start)
        # 2 - If the past_length is smaller than input_ids', then input_ids holds all input tokens. We can discard
        # input_ids based on the past_length.
        elif past_length < input_ids.shape[1]:
            input_ids = input_ids.narrow(
                1, past_length, input_ids.size(1) - past_length
            )
        # 3 - Otherwise (past_length >= input_ids.shape[1]), let's assume input_ids only has unprocessed tokens.

        # If we are about to go beyond the maximum cache length, we need to crop the input attention mask.
        if (
            max_cache_length is not None
            and attention_mask is not None
            and cache_length + input_ids.shape[1] > max_cache_length
        ):
            attention_mask = attention_mask.narrow(
                1, -max_cache_length, max_cache_length
            )

    if attention_mask is not None and position_ids is None:
        # create position_ids on the fly for batch generation
        position_ids = attention_mask.long().cumsum(-1) - 1
        position_ids.masked_fill_(attention_mask.eq(0), 1)
        if past_key_values:
            position_ids = position_ids.narrow(
                1, -input_ids.shape[1], input_ids.shape[1]
            )

    input_length = (
        position_ids.shape[-1] if position_ids is not None else input_ids.shape[-1]
    )
    if cache_position is None:
        cache_position = torch.arange(
            past_length, past_length + input_length, device=input_ids.device
        )
    else:
        cache_position = cache_position.narrow(0, -input_length, input_length)

    if has_static_cache:
        past_key_values = None

    model_inputs = self._GenerationInputs(
        position_ids=position_ids,
        cache_position=cache_position,
        use_cache=use_cache,
    )

    # if `inputs_embeds` are passed, we only want to use them in the 1st generation step
    if inputs_embeds is not None and past_key_values is None:
        model_inputs.inputs_embeds = inputs_embeds
    else:
        # The `contiguous()` here is necessary to have a static stride during decoding. torchdynamo otherwise
        # recompiles graphs as the stride of the inputs is a guard. Ref: https://github.com/huggingface/transformers/pull/29114
        # TODO: use `next_tokens` directly instead.
        model_inputs.input_ids = input_ids.contiguous()

    model_inputs.past_key_values = past_key_values
    model_inputs.attention_mask = attention_mask

    return model_inputs

def _prepare_generation_inputs(
    self,
    input_ids: torch.Tensor,
    past_key_values: Optional[Tuple[Tuple[torch.FloatTensor]]] = None,
    attention_mask: Optional[torch.Tensor] = None,
    inputs_embeds: Optional[torch.Tensor] = None,
    cache_position: Optional[torch.Tensor] = None,
    position_ids: Optional[torch.Tensor] = None,
    use_cache=True,
) -> _GenerationInputs:
    # With static cache, the `past_key_values` is None
    # TODO joao: standardize interface for the different Cache classes and remove of this if
    has_static_cache = False
    if past_key_values is None:
        if hasattr(self.gpt.layers[0], "self_attn"):
            past_key_values = getattr(
                self.gpt.layers[0].self_attn, "past_key_value", None
            )
        has_static_cache = past_key_values is not None

    past_length = 0
    if past_key_values is not None:
        if isinstance(past_key_values, Cache):
            past_length = (
                int(cache_position[0])
                if cache_position is not None
                else past_key_values.get_seq_length()
            )
            try:
                max_cache_length = past_key_values.get_max_cache_shape()
            except:
                max_cache_length = (
                    past_key_values.get_max_length()
                )  # deprecated in transformers 4.48
            cache_length = (
                past_length
                if max_cache_length is None
                else min(max_cache_length, past_length)
            )
        # TODO joao: remove this `else` after `generate` prioritizes `Cache` objects
        else:
            cache_length = past_length = past_key_values[0][0].shape[2]
            max_cache_length = None

        # Keep only the unprocessed tokens:
        # 1 - If the length of the attention_mask exceeds the length of input_ids, then we are in a setting where
        # some of the inputs are exclusively passed as part of the cache (e.g. when passing input_embeds as
        # input)
        if (
            attention_mask is not None
            and attention_mask.shape[1] > input_ids.shape[1]
        ):
            start = attention_mask.shape[1] - past_length
            input_ids = input_ids.narrow(1, -start, start)
        # 2 - If the past_length is smaller than input_ids', then input_ids holds all input tokens. We can discard
        # input_ids based on the past_length.
        elif past_length < input_ids.shape[1]:
            input_ids = input_ids.narrow(
                1, past_length, input_ids.size(1) - past_length
            )
        # 3 - Otherwise (past_length >= input_ids.shape[1]), let's assume input_ids only has unprocessed tokens.

        # If we are about to go beyond the maximum cache length, we need to crop the input attention mask.
        if (
            max_cache_length is not None
            and attention_mask is not None
            and cache_length + input_ids.shape[1] > max_cache_length
        ):
            attention_mask = attention_mask.narrow(
                1, -max_cache_length, max_cache_length
            )

    if attention_mask is not None and position_ids is None:
        # create position_ids on the fly for batch generation
        position_ids = attention_mask.long().cumsum(-1) - 1
        position_ids.masked_fill_(attention_mask.eq(0), 1)
        if past_key_values:
            position_ids = position_ids.narrow(
                1, -input_ids.shape[1], input_ids.shape[1]
            )

    input_length = (
        position_ids.shape[-1] if position_ids is not None else input_ids.shape[-1]
    )
    if cache_position is None:
        cache_position = torch.arange(
            past_length, past_length + input_length, device=input_ids.device
        )
    else:
        cache_position = cache_position.narrow(0, -input_length, input_length)

    if has_static_cache:
        past_key_values = None

    model_inputs = self._GenerationInputs(
        position_ids=position_ids,
        cache_position=cache_position,
        use_cache=use_cache,
    )

    # if `inputs_embeds` are passed, we only want to use them in the 1st generation step
    if inputs_embeds is not None and past_key_values is None:
        model_inputs.inputs_embeds = inputs_embeds
    else:
        # The `contiguous()` here is necessary to have a static stride during decoding. torchdynamo otherwise
        # recompiles graphs as the stride of the inputs is a guard. Ref: https://github.com/huggingface/transformers/pull/29114
        # TODO: use `next_tokens` directly instead.
        model_inputs.input_ids = input_ids.contiguous()

    model_inputs.past_key_values = past_key_values
    model_inputs.attention_mask = attention_mask

    return model_inputs

