def assert_signatures_in_sync(
    source_func: Callable[..., Any],
    check_func: Callable[..., Any],
    *,
    exclude_params: set[str] = set(),
    description: str = "",
) -> None:
    """Ensure that the signature of the second function matches the first."""

    check_sig = inspect.signature(check_func)
    source_sig = inspect.signature(source_func)

    errors: list[str] = []

    for name, source_param in source_sig.parameters.items():
        if name in exclude_params:
            continue

        custom_param = check_sig.parameters.get(name)
        if not custom_param:
            errors.append(f"the `{name}` param is missing")
            continue

        if custom_param.annotation != source_param.annotation:
            errors.append(
                f"types for the `{name}` param are do not match; source={repr(source_param.annotation)} checking={repr(custom_param.annotation)}"
            )
            continue

    if errors:
        raise AssertionError(
            f"{len(errors)} errors encountered when comparing signatures{description}:\n\n" + "\n\n".join(errors)
        )

def request(self, method, url, stream=False, data=None, params=None,
             headers=None, **kw):
    tid = urlparse(url).path.split("/")[-1]

    response = Mock()
    response.headers = {"content-type": "application/json"}
    response.status_code = 200
    response.content = b''

    if method == "GET":
        if tid not in self._store:
            return self._not_found_response()
        response.content = self._store.get(tid)
    elif method == "PUT":
        self._store[tid] = data
        response.content = str_to_bytes(f'{{"ok":true,"id":"{tid}","rev":"1-revid"}}')
    elif method == "HEAD":
        if tid not in self._store:
            return self._not_found_response()
        response.headers.update({"etag": "1-revid"})
    elif method == "DELETE":
        if tid not in self._store:
            return self._not_found_response()
        del self._store[tid]
        response.content = str_to_bytes(f'{{"ok":true,"id":"{tid}","rev":"1-revid"}}')
    else:
        raise NotImplemented(f"CouchSessionMock.request() does not handle {method} method")

    return response

def get_results(self, name: str, artists: List[str], **_) -> Dict[str, str]:
    """
    Returns the results for the given song.

    ### Arguments
    - name: The name of the song.
    - artists: The artists of the song.
    - kwargs: Additional arguments.

    ### Returns
    - A dictionary with the results. (The key is the title and the value is the url.)
    """

    if self.x_code is None:
        self.x_code = self.get_x_code()

    if self.x_code is None:
        return {}

    # Join every artist by comma in artists
    artist_str = ", ".join(artist for artist in artists if artist)

    params = {
        "q": f"{artist_str} - {name}",
        "x": self.x_code,
    }

    counter = 0
    soup = None
    while counter < 4:
        try:
            response = self.session.get(
                "https://search.azlyrics.com/search.php", params=params
            )
        except requests.ConnectionError:
            continue

        if not response.ok:
            counter += 1
            continue

        soup = BeautifulSoup(response.content, "html.parser")
        break

    if soup is None:
        return {}

    td_tags = soup.find_all("td")
    if len(td_tags) == 0:
        return {}

    results = {}
    for td_tag in td_tags:
        a_tags = td_tag.find_all("a", href=True)
        if len(a_tags) == 0:
            continue

        a_tag = a_tags[0]
        url = a_tag["href"].strip()
        if url == "":
            continue

        title = td_tag.find("span").get_text().strip()
        artist = td_tag.find("b").get_text().strip()

        results[f"{artist} - {title}"] = url

    return results

def get_env_value(
    env_key: str, default: any, value_type: type = str, special_none: bool = False
) -> any:
    """
    Get value from environment variable with type conversion

    Args:
        env_key (str): Environment variable key
        default (any): Default value if env variable is not set
        value_type (type): Type to convert the value to
        special_none (bool): If True, return None when value is "None"

    Returns:
        any: Converted value from environment or default
    """
    value = os.getenv(env_key)
    if value is None:
        return default

    # Handle special case for "None" string
    if special_none and value == "None":
        return None

    if value_type is bool:
        return value.lower() in ("true", "1", "yes", "t", "on")
    try:
        return value_type(value)
    except (ValueError, TypeError):
        return default

async def query(
    self,
    sql: str,
    params: list[Any] | None = None,
    multirows: bool = False,
    with_age: bool = False,
    graph_name: str | None = None,
) -> dict[str, Any] | None | list[dict[str, Any]]:
    async with self.pool.acquire() as connection:  # type: ignore
        if with_age and graph_name:
            await self.configure_age(connection, graph_name)  # type: ignore
        elif with_age and not graph_name:
            raise ValueError("Graph name is required when with_age is True")

        try:
            if params:
                rows = await connection.fetch(sql, *params)
            else:
                rows = await connection.fetch(sql)

            if multirows:
                if rows:
                    columns = [col for col in rows[0].keys()]
                    data = [dict(zip(columns, row)) for row in rows]
                else:
                    data = []
            else:
                if rows:
                    columns = rows[0].keys()
                    data = dict(zip(columns, rows[0]))
                else:
                    data = None

            return data
        except Exception as e:
            logger.error(f"PostgreSQL database, error:{e}")
            raise

async def execute(
    self,
    sql: str,
    data: dict[str, Any] | None = None,
    upsert: bool = False,
    ignore_if_exists: bool = False,
    with_age: bool = False,
    graph_name: str | None = None,
):
    try:
        async with self.pool.acquire() as connection:  # type: ignore
            if with_age and graph_name:
                await self.configure_age(connection, graph_name)
            elif with_age and not graph_name:
                raise ValueError("Graph name is required when with_age is True")

            if data is None:
                await connection.execute(sql)
            else:
                await connection.execute(sql, *data.values())
    except (
        asyncpg.exceptions.UniqueViolationError,
        asyncpg.exceptions.DuplicateTableError,
        asyncpg.exceptions.DuplicateObjectError,  # Catch "already exists" error
        asyncpg.exceptions.InvalidSchemaNameError,  # Also catch for AGE extension "already exists"
    ) as e:
        if ignore_if_exists:
            # If the flag is set, just ignore these specific errors
            pass
        elif upsert:
            print("Key value duplicate, but upsert succeeded.")
        else:
            logger.error(f"Upsert error: {e}")
    except Exception as e:
        logger.error(f"PostgreSQL database,\nsql:{sql},\ndata:{data},\nerror:{e}")
        raise

async def get_by_ids(self, ids: list[str]) -> list[dict[str, Any]]:
    """Get data by ids"""
    sql = SQL_TEMPLATES["get_by_ids_" + self.namespace].format(
        ids=",".join([f"'{id}'" for id in ids])
    )
    params = {"workspace": self.workspace}
    results = await self.db.query(sql, list(params.values()), multirows=True)

    if results and is_namespace(self.namespace, NameSpace.KV_STORE_TEXT_CHUNKS):
        # Parse llm_cache_list JSON string back to list for each result
        for result in results:
            llm_cache_list = result.get("llm_cache_list", [])
            if isinstance(llm_cache_list, str):
                try:
                    llm_cache_list = json.loads(llm_cache_list)
                except json.JSONDecodeError:
                    llm_cache_list = []
            result["llm_cache_list"] = llm_cache_list
            create_time = result.get("create_time", 0)
            update_time = result.get("update_time", 0)
            result["create_time"] = create_time
            result["update_time"] = create_time if update_time == 0 else update_time

    # Special handling for LLM cache to ensure compatibility with _get_cached_extraction_results
    if results and is_namespace(
        self.namespace, NameSpace.KV_STORE_LLM_RESPONSE_CACHE
    ):
        processed_results = []
        for row in results:
            create_time = row.get("create_time", 0)
            update_time = row.get("update_time", 0)
            # Parse queryparam JSON string back to dict
            queryparam = row.get("queryparam")
            if isinstance(queryparam, str):
                try:
                    queryparam = json.loads(queryparam)
                except json.JSONDecodeError:
                    queryparam = None
            # Map field names for compatibility (mode field removed)
            processed_row = {
                **row,
                "return": row.get("return_value", ""),
                "cache_type": row.get("cache_type"),
                "original_prompt": row.get("original_prompt", ""),
                "chunk_id": row.get("chunk_id"),
                "queryparam": queryparam,
                "create_time": create_time,
                "update_time": create_time if update_time == 0 else update_time,
            }
            processed_results.append(processed_row)
        return processed_results

    # Special handling for FULL_ENTITIES namespace
    if results and is_namespace(self.namespace, NameSpace.KV_STORE_FULL_ENTITIES):
        for result in results:
            # Parse entity_names JSON string back to list
            entity_names = result.get("entity_names", [])
            if isinstance(entity_names, str):
                try:
                    entity_names = json.loads(entity_names)
                except json.JSONDecodeError:
                    entity_names = []
            result["entity_names"] = entity_names
            create_time = result.get("create_time", 0)
            update_time = result.get("update_time", 0)
            result["create_time"] = create_time
            result["update_time"] = create_time if update_time == 0 else update_time

    # Special handling for FULL_RELATIONS namespace
    if results and is_namespace(self.namespace, NameSpace.KV_STORE_FULL_RELATIONS):
        for result in results:
            # Parse relation_pairs JSON string back to list
            relation_pairs = result.get("relation_pairs", [])
            if isinstance(relation_pairs, str):
                try:
                    relation_pairs = json.loads(relation_pairs)
                except json.JSONDecodeError:
                    relation_pairs = []
            result["relation_pairs"] = relation_pairs
            create_time = result.get("create_time", 0)
            update_time = result.get("update_time", 0)
            result["create_time"] = create_time
            result["update_time"] = create_time if update_time == 0 else update_time

    return results if results else []

async def upsert(self, data: dict[str, dict[str, Any]]) -> None:
    logger.debug(f"[{self.workspace}] Inserting {len(data)} to {self.namespace}")
    if not data:
        return

    if is_namespace(self.namespace, NameSpace.KV_STORE_TEXT_CHUNKS):
        # Get current UTC time and convert to naive datetime for database storage
        current_time = datetime.datetime.now(timezone.utc).replace(tzinfo=None)
        for k, v in data.items():
            upsert_sql = SQL_TEMPLATES["upsert_text_chunk"]
            _data = {
                "workspace": self.workspace,
                "id": k,
                "tokens": v["tokens"],
                "chunk_order_index": v["chunk_order_index"],
                "full_doc_id": v["full_doc_id"],
                "content": v["content"],
                "file_path": v["file_path"],
                "llm_cache_list": json.dumps(v.get("llm_cache_list", [])),
                "create_time": current_time,
                "update_time": current_time,
            }
            await self.db.execute(upsert_sql, _data)
    elif is_namespace(self.namespace, NameSpace.KV_STORE_FULL_DOCS):
        for k, v in data.items():
            upsert_sql = SQL_TEMPLATES["upsert_doc_full"]
            _data = {
                "id": k,
                "content": v["content"],
                "workspace": self.workspace,
            }
            await self.db.execute(upsert_sql, _data)
    elif is_namespace(self.namespace, NameSpace.KV_STORE_LLM_RESPONSE_CACHE):
        for k, v in data.items():
            upsert_sql = SQL_TEMPLATES["upsert_llm_response_cache"]
            _data = {
                "workspace": self.workspace,
                "id": k,  # Use flattened key as id
                "original_prompt": v["original_prompt"],
                "return_value": v["return"],
                "chunk_id": v.get("chunk_id"),
                "cache_type": v.get(
                    "cache_type", "extract"
                ),  # Get cache_type from data
                "queryparam": json.dumps(v.get("queryparam"))
                if v.get("queryparam")
                else None,
            }

            await self.db.execute(upsert_sql, _data)
    elif is_namespace(self.namespace, NameSpace.KV_STORE_FULL_ENTITIES):
        # Get current UTC time and convert to naive datetime for database storage
        current_time = datetime.datetime.now(timezone.utc).replace(tzinfo=None)
        for k, v in data.items():
            upsert_sql = SQL_TEMPLATES["upsert_full_entities"]
            _data = {
                "workspace": self.workspace,
                "id": k,
                "entity_names": json.dumps(v["entity_names"]),
                "count": v["count"],
                "create_time": current_time,
                "update_time": current_time,
            }
            await self.db.execute(upsert_sql, _data)
    elif is_namespace(self.namespace, NameSpace.KV_STORE_FULL_RELATIONS):
        # Get current UTC time and convert to naive datetime for database storage
        current_time = datetime.datetime.now(timezone.utc).replace(tzinfo=None)
        for k, v in data.items():
            upsert_sql = SQL_TEMPLATES["upsert_full_relations"]
            _data = {
                "workspace": self.workspace,
                "id": k,
                "relation_pairs": json.dumps(v["relation_pairs"]),
                "count": v["count"],
                "create_time": current_time,
                "update_time": current_time,
            }
            await self.db.execute(upsert_sql, _data)

async def query(
    self, query: str, top_k: int, query_embedding: list[float] = None
) -> list[dict[str, Any]]:
    if query_embedding is not None:
        embedding = query_embedding
    else:
        embeddings = await self.embedding_func(
            [query], _priority=5
        )  # higher priority for query
        embedding = embeddings[0]

    embedding_string = ",".join(map(str, embedding))

    sql = SQL_TEMPLATES[self.namespace].format(embedding_string=embedding_string)
    params = {
        "workspace": self.workspace,
        "closer_than_threshold": 1 - self.cosine_better_than_threshold,
        "top_k": top_k,
    }
    results = await self.db.query(sql, params=list(params.values()), multirows=True)
    return results

async def delete(self, ids: list[str]) -> None:
    """Delete vectors with specified IDs from the storage.

    Args:
        ids: List of vector IDs to be deleted
    """
    if not ids:
        return

    table_name = namespace_to_table_name(self.namespace)
    if not table_name:
        logger.error(
            f"[{self.workspace}] Unknown namespace for vector deletion: {self.namespace}"
        )
        return

    delete_sql = f"DELETE FROM {table_name} WHERE workspace=$1 AND id = ANY($2)"

    try:
        await self.db.execute(delete_sql, {"workspace": self.workspace, "ids": ids})
        logger.debug(
            f"[{self.workspace}] Successfully deleted {len(ids)} vectors from {self.namespace}"
        )
    except Exception as e:
        logger.error(
            f"[{self.workspace}] Error while deleting vectors from {self.namespace}: {e}"
        )

async def delete_entity_relation(self, entity_name: str) -> None:
    """Delete all relations associated with an entity.

    Args:
        entity_name: The name of the entity whose relations should be deleted
    """
    try:
        # Delete relations where the entity is either the source or target
        delete_sql = """DELETE FROM LIGHTRAG_VDB_RELATION
                        WHERE workspace=$1 AND (source_id=$2 OR target_id=$2)"""

        await self.db.execute(
            delete_sql, {"workspace": self.workspace, "entity_name": entity_name}
        )
        logger.debug(
            f"[{self.workspace}] Successfully deleted relations for entity {entity_name}"
        )
    except Exception as e:
        logger.error(
            f"[{self.workspace}] Error deleting relations for entity {entity_name}: {e}"
        )

async def get_by_id(self, id: str) -> dict[str, Any] | None:
    """Get vector data by its ID

    Args:
        id: The unique identifier of the vector

    Returns:
        The vector data if found, or None if not found
    """
    table_name = namespace_to_table_name(self.namespace)
    if not table_name:
        logger.error(
            f"[{self.workspace}] Unknown namespace for ID lookup: {self.namespace}"
        )
        return None

    query = f"SELECT *, EXTRACT(EPOCH FROM create_time)::BIGINT as created_at FROM {table_name} WHERE workspace=$1 AND id=$2"
    params = {"workspace": self.workspace, "id": id}

    try:
        result = await self.db.query(query, list(params.values()))
        if result:
            return dict(result)
        return None
    except Exception as e:
        logger.error(
            f"[{self.workspace}] Error retrieving vector data for ID {id}: {e}"
        )
        return None

async def get_vectors_by_ids(self, ids: list[str]) -> dict[str, list[float]]:
    """Get vectors by their IDs, returning only ID and vector data for efficiency

    Args:
        ids: List of unique identifiers

    Returns:
        Dictionary mapping IDs to their vector embeddings
        Format: {id: [vector_values], ...}
    """
    if not ids:
        return {}

    table_name = namespace_to_table_name(self.namespace)
    if not table_name:
        logger.error(
            f"[{self.workspace}] Unknown namespace for vector lookup: {self.namespace}"
        )
        return {}

    ids_str = ",".join([f"'{id}'" for id in ids])
    query = f"SELECT id, content_vector FROM {table_name} WHERE workspace=$1 AND id IN ({ids_str})"
    params = {"workspace": self.workspace}

    try:
        results = await self.db.query(query, list(params.values()), multirows=True)
        vectors_dict = {}

        for result in results:
            if result and "content_vector" in result and "id" in result:
                try:
                    # Parse JSON string to get vector as list of floats
                    vector_data = json.loads(result["content_vector"])
                    if isinstance(vector_data, list):
                        vectors_dict[result["id"]] = vector_data
                except (json.JSONDecodeError, TypeError) as e:
                    logger.warning(
                        f"[{self.workspace}] Failed to parse vector data for ID {result['id']}: {e}"
                    )

        return vectors_dict
    except Exception as e:
        logger.error(
            f"[{self.workspace}] Error retrieving vectors by IDs from {self.namespace}: {e}"
        )
        return {}

async def drop(self) -> dict[str, str]:
    """Drop the storage"""
    async with get_storage_lock():
        try:
            table_name = namespace_to_table_name(self.namespace)
            if not table_name:
                return {
                    "status": "error",
                    "message": f"Unknown namespace: {self.namespace}",
                }

            drop_sql = SQL_TEMPLATES["drop_specifiy_table_workspace"].format(
                table_name=table_name
            )
            await self.db.execute(drop_sql, {"workspace": self.workspace})
            return {"status": "success", "message": "data dropped"}
        except Exception as e:
            return {"status": "error", "message": str(e)}

async def has_node(self, node_id: str) -> bool:
    query = f"""
        SELECT EXISTS (
          SELECT 1
          FROM {self.graph_name}.base
          WHERE ag_catalog.agtype_access_operator(
                  VARIADIC ARRAY[properties, '"entity_id"'::agtype]
                ) = (to_json($1::text)::text)::agtype
          LIMIT 1
        ) AS node_exists;
    """

    params = {"node_id": node_id}
    row = (await self._query(query, params=params))[0]
    return bool(row["node_exists"])

async def get_nodes_batch(
    self, node_ids: list[str], batch_size: int = 1000
) -> dict[str, dict]:
    """
    Retrieve multiple nodes in one query using UNWIND.

    Args:
        node_ids: List of node entity IDs to fetch.
        batch_size: Batch size for the query

    Returns:
        A dictionary mapping each node_id to its node data (or None if not found).
    """
    if not node_ids:
        return {}

    seen = set()
    unique_ids = []
    for nid in node_ids:
        nid_norm = self._normalize_node_id(nid)
        if nid_norm not in seen:
            seen.add(nid_norm)
            unique_ids.append(nid_norm)

    # Build result dictionary
    nodes_dict = {}

    for i in range(0, len(unique_ids), batch_size):
        batch = unique_ids[i : i + batch_size]

        query = f"""
            WITH input(v, ord) AS (
              SELECT v, ord
              FROM unnest($1::text[]) WITH ORDINALITY AS t(v, ord)
            ),
            ids(node_id, ord) AS (
              SELECT (to_json(v)::text)::agtype AS node_id, ord
              FROM input
            )
            SELECT i.node_id::text AS node_id,
                   b.properties
            FROM {self.graph_name}.base AS b
            JOIN ids i
              ON ag_catalog.agtype_access_operator(
                   VARIADIC ARRAY[b.properties, '"entity_id"'::agtype]
                 ) = i.node_id
            ORDER BY i.ord;
        """

        results = await self._query(query, params={"ids": batch})

        for result in results:
            if result["node_id"] and result["properties"]:
                node_dict = result["properties"]

                # Process string result, parse it to JSON dictionary
                if isinstance(node_dict, str):
                    try:
                        node_dict = json.loads(node_dict)
                    except json.JSONDecodeError:
                        logger.warning(
                            f"Failed to parse node string in batch: {node_dict}"
                        )

                nodes_dict[result["node_id"]] = node_dict

    return nodes_dict

async def get_edges_by_chunk_ids(self, chunk_ids: list[str]) -> list[dict]:
    """
    Retrieves edges from the graph that are associated with a given list of chunk IDs.
    This method uses a Cypher query with UNWIND to efficiently find all edges
    where the `source_id` property contains any of the specified chunk IDs.
    """
    chunk_ids_str = json.dumps(chunk_ids)

    query = f"""
        SELECT * FROM cypher('{self.graph_name}', $$
            UNWIND {chunk_ids_str} AS chunk_id
            MATCH ()-[r]-()
            WHERE r.source_id IS NOT NULL AND chunk_id IN split(r.source_id, '{GRAPH_FIELD_SEP}')
            RETURN DISTINCT r, startNode(r) AS source, endNode(r) AS target
        $$) AS (edge agtype, source agtype, target agtype);
    """
    results = await self._query(query)
    edges = []
    if results:
        for item in results:
            edge_agtype = item["edge"]["properties"]
            # Process string result, parse it to JSON dictionary
            if isinstance(edge_agtype, str):
                try:
                    edge_agtype = json.loads(edge_agtype)
                except json.JSONDecodeError:
                    logger.warning(
                        f"[{self.workspace}] Failed to parse edge string in batch: {edge_agtype}"
                    )

            source_agtype = item["source"]["properties"]
            # Process string result, parse it to JSON dictionary
            if isinstance(source_agtype, str):
                try:
                    source_agtype = json.loads(source_agtype)
                except json.JSONDecodeError:
                    logger.warning(
                        f"[{self.workspace}] Failed to parse node string in batch: {source_agtype}"
                    )

            target_agtype = item["target"]["properties"]
            # Process string result, parse it to JSON dictionary
            if isinstance(target_agtype, str):
                try:
                    target_agtype = json.loads(target_agtype)
                except json.JSONDecodeError:
                    logger.warning(
                        f"[{self.workspace}] Failed to parse node string in batch: {target_agtype}"
                    )

            if edge_agtype and source_agtype and target_agtype:
                edge_properties = edge_agtype
                edge_properties["source"] = source_agtype["entity_id"]
                edge_properties["target"] = target_agtype["entity_id"]
                edges.append(edge_properties)
    return edges

class ResponseStreamState(Generic[TextFormatT]):
    def __init__(
        self,
        *,
        input_tools: Iterable[ToolParam] | NotGiven,
        text_format: type[TextFormatT] | NotGiven,
    ) -> None:
        self.__current_snapshot: ParsedResponseSnapshot | None = None
        self._completed_response: ParsedResponse[TextFormatT] | None = None
        self._input_tools = [tool for tool in input_tools] if is_given(input_tools) else []
        self._text_format = text_format
        self._rich_text_format: type | NotGiven = text_format if inspect.isclass(text_format) else NOT_GIVEN

    def handle_event(self, event: RawResponseStreamEvent) -> List[ResponseStreamEvent[TextFormatT]]:
        self.__current_snapshot = snapshot = self.accumulate_event(event)

        events: List[ResponseStreamEvent[TextFormatT]] = []

        if event.type == "response.output_text.delta":
            output = snapshot.output[event.output_index]
            assert output.type == "message"

            content = output.content[event.content_index]
            assert content.type == "output_text"

            events.append(
                build(
                    ResponseTextDeltaEvent,
                    content_index=event.content_index,
                    delta=event.delta,
                    item_id=event.item_id,
                    output_index=event.output_index,
                    sequence_number=event.sequence_number,
                    logprobs=event.logprobs,
                    type="response.output_text.delta",
                    snapshot=content.text,
                )
            )
        elif event.type == "response.output_text.done":
            output = snapshot.output[event.output_index]
            assert output.type == "message"

            content = output.content[event.content_index]
            assert content.type == "output_text"

            events.append(
                build(
                    ResponseTextDoneEvent[TextFormatT],
                    content_index=event.content_index,
                    item_id=event.item_id,
                    output_index=event.output_index,
                    sequence_number=event.sequence_number,
                    logprobs=event.logprobs,
                    type="response.output_text.done",
                    text=event.text,
                    parsed=parse_text(event.text, text_format=self._text_format),
                )
            )
        elif event.type == "response.function_call_arguments.delta":
            output = snapshot.output[event.output_index]
            assert output.type == "function_call"

            events.append(
                build(
                    ResponseFunctionCallArgumentsDeltaEvent,
                    delta=event.delta,
                    item_id=event.item_id,
                    output_index=event.output_index,
                    sequence_number=event.sequence_number,
                    type="response.function_call_arguments.delta",
                    snapshot=output.arguments,
                )
            )

        elif event.type == "response.completed":
            response = self._completed_response
            assert response is not None

            events.append(
                build(
                    ResponseCompletedEvent,
                    sequence_number=event.sequence_number,
                    type="response.completed",
                    response=response,
                )
            )
        else:
            events.append(event)

        return events

    def accumulate_event(self, event: RawResponseStreamEvent) -> ParsedResponseSnapshot:
        snapshot = self.__current_snapshot
        if snapshot is None:
            return self._create_initial_response(event)

        if event.type == "response.output_item.added":
            if event.item.type == "function_call":
                snapshot.output.append(
                    construct_type_unchecked(
                        type_=cast(Any, ParsedResponseFunctionToolCall), value=event.item.to_dict()
                    )
                )
            elif event.item.type == "message":
                snapshot.output.append(
                    construct_type_unchecked(type_=cast(Any, ParsedResponseOutputMessage), value=event.item.to_dict())
                )
            else:
                snapshot.output.append(event.item)
        elif event.type == "response.content_part.added":
            output = snapshot.output[event.output_index]
            if output.type == "message":
                output.content.append(
                    construct_type_unchecked(type_=cast(Any, ParsedContent), value=event.part.to_dict())
                )
        elif event.type == "response.output_text.delta":
            output = snapshot.output[event.output_index]
            if output.type == "message":
                content = output.content[event.content_index]
                assert content.type == "output_text"
                content.text += event.delta
        elif event.type == "response.function_call_arguments.delta":
            output = snapshot.output[event.output_index]
            if output.type == "function_call":
                output.arguments += event.delta
        elif event.type == "response.completed":
            self._completed_response = parse_response(
                text_format=self._text_format,
                response=event.response,
                input_tools=self._input_tools,
            )

        return snapshot

    def _create_initial_response(self, event: RawResponseStreamEvent) -> ParsedResponseSnapshot:
        if event.type != "response.created":
            raise RuntimeError(f"Expected to have received `response.created` before `{event.type}`")

        return construct_type_unchecked(type_=ParsedResponseSnapshot, value=event.response.to_dict())

def parse_issue(issue, field_mapping):  # noqa: C901
    result = OrderedDict()

    # Handle API v3 response format: key field may be missing, use id as fallback
    result["key"] = issue.get("key", issue.get("id", "unknown"))

    # Handle API v3 response format: fields may be missing
    fields = issue.get("fields", {})
    for k, v in fields.items():  #
        output_name = field_mapping.get_output_field_name(k)
        member_names = field_mapping.get_dict_members(k)

        if isinstance(v, dict):
            if len(member_names) > 0:
                # if field mapping with dict member mappings defined get value of each member
                for member_name in member_names:
                    if member_name in v:
                        result[field_mapping.get_dict_output_field_name(k, member_name)] = v[member_name]

            else:
                # these special mapping rules are kept for backwards compatibility
                if "key" in v:
                    result["{}_key".format(output_name)] = v["key"]
                if "name" in v:
                    result["{}_name".format(output_name)] = v["name"]

                if k in v:
                    result[output_name] = v[k]

                if "watchCount" in v:
                    result[output_name] = v["watchCount"]

        elif isinstance(v, list):
            if len(member_names) > 0:
                # if field mapping with dict member mappings defined get value of each member
                for member_name in member_names:
                    listValues = []
                    for listItem in v:
                        if isinstance(listItem, dict):
                            if member_name in listItem:
                                listValues.append(listItem[member_name])
                    if len(listValues) > 0:
                        result[field_mapping.get_dict_output_field_name(k, member_name)] = ",".join(listValues)

            else:
                # otherwise support list values only for non-dict items
                listValues = []
                for listItem in v:
                    if not isinstance(listItem, dict):
                        listValues.append(listItem)
                if len(listValues) > 0:
                    result[output_name] = ",".join(listValues)

        else:
            result[output_name] = v

    return result

class ResultConsumer(BaseResultConsumer):
    _pubsub = None

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._get_key_for_task = self.backend.get_key_for_task
        self._decode_result = self.backend.decode_result
        self._ensure = self.backend.ensure
        self._connection_errors = self.backend.connection_errors
        self.subscribed_to = set()

    def on_after_fork(self):
        try:
            self.backend.client.connection_pool.reset()
            if self._pubsub is not None:
                self._pubsub.close()
        except KeyError as e:
            logger.warning(str(e))
        super().on_after_fork()

    def _reconnect_pubsub(self):
        self._pubsub = None
        self.backend.client.connection_pool.reset()
        # task state might have changed when the connection was down so we
        # retrieve meta for all subscribed tasks before going into pubsub mode
        if self.subscribed_to:
            metas = self.backend.client.mget(self.subscribed_to)
            metas = [meta for meta in metas if meta]
            for meta in metas:
                self.on_state_change(self._decode_result(meta), None)
        self._pubsub = self.backend.client.pubsub(
            ignore_subscribe_messages=True,
        )
        # subscribed_to maybe empty after on_state_change
        if self.subscribed_to:
            self._pubsub.subscribe(*self.subscribed_to)
        else:
            self._pubsub.connection = self._pubsub.connection_pool.get_connection(
                'pubsub', self._pubsub.shard_hint
            )
            # even if there is nothing to subscribe, we should not lose the callback after connecting.
            # The on_connect callback will re-subscribe to any channels we previously subscribed to.
            self._pubsub.connection.register_connect_callback(self._pubsub.on_connect)

    @contextmanager
    def reconnect_on_error(self):
        try:
            yield
        except self._connection_errors:
            try:
                self._ensure(self._reconnect_pubsub, ())
            except self._connection_errors:
                logger.critical(E_RETRY_LIMIT_EXCEEDED)
                raise

    def _maybe_cancel_ready_task(self, meta):
        if meta['status'] in states.READY_STATES:
            self.cancel_for(meta['task_id'])

    def on_state_change(self, meta, message):
        super().on_state_change(meta, message)
        self._maybe_cancel_ready_task(meta)

    def start(self, initial_task_id, **kwargs):
        self._pubsub = self.backend.client.pubsub(
            ignore_subscribe_messages=True,
        )
        self._consume_from(initial_task_id)

    def on_wait_for_pending(self, result, **kwargs):
        for meta in result._iter_meta(**kwargs):
            if meta is not None:
                self.on_state_change(meta, None)

    def stop(self):
        if self._pubsub is not None:
            self._pubsub.close()

    def drain_events(self, timeout=None):
        if self._pubsub:
            with self.reconnect_on_error():
                message = self._pubsub.get_message(timeout=timeout)
                if message and message['type'] == 'message':
                    self.on_state_change(self._decode_result(message['data']), message)
        elif timeout:
            time.sleep(timeout)

    def consume_from(self, task_id):
        if self._pubsub is None:
            return self.start(task_id)
        self._consume_from(task_id)

    def _consume_from(self, task_id):
        key = self._get_key_for_task(task_id)
        if key not in self.subscribed_to:
            self.subscribed_to.add(key)
            with self.reconnect_on_error():
                self._pubsub.subscribe(key)

    def cancel_for(self, task_id):
        key = self._get_key_for_task(task_id)
        self.subscribed_to.discard(key)
        if self._pubsub:
            with self.reconnect_on_error():
                self._pubsub.unsubscribe(key)

def checkAndReloadIfNeeded(self):
    now = int(time.time() * 1000)
    if now - self.memory_cache["last_check"] < CACHE_CHECK_INTERVAL_MS:
        return
    self.memory_cache["last_check"] = now

    try:
        file_path = self.getCredentialFilePath()
        stat = file_path.stat()
        file_mod_time = int(stat.st_mtime * 1000)
        if file_mod_time > self.memory_cache["file_mod_time"]:
            await self.reloadCredentialsFromFile()
            self.memory_cache["file_mod_time"] = file_mod_time
    except FileNotFoundError:
        self.memory_cache["file_mod_time"] = 0
    except Exception as e:
        self.memory_cache["credentials"] = None
        raise TokenManagerError(TokenError.FILE_ACCESS_ERROR, str(e), e)

