def _handle_message(self, msg):
    """Override message handling to support request-response"""
    parsed_msg = super()._handle_message(msg)
    self._log.debug(f"Received message: {parsed_msg}")
    if parsed_msg is None:
        return None
    req_id, exception = None, None
    if "id" in parsed_msg:
        req_id = parsed_msg["id"]
    if "status" in parsed_msg:
        if parsed_msg["status"] != 200:
            exception = BinanceAPIException(
                parsed_msg, parsed_msg["status"], self.json_dumps(parsed_msg["error"])
            )
    if req_id is not None and req_id in self._responses:
        if exception is not None:
            self._responses[req_id].set_exception(exception)
        else:
            self._responses[req_id].set_result(parsed_msg)
    elif exception is not None:
        raise exception
    else:
        self._log.warning(f"WS api receieved unknown message: {parsed_msg}")

def init(context):
    context.count = 0

    subscribe_event(EVENT.TRADE, on_trade)

def __eq__(self, other):
    if isinstance(other, Thread):
        return self.id == other.id
    return super().__eq__(other)

async def from_channel(cls, manager: "ThreadManager", channel: discord.TextChannel) -> "Thread":
    # there is a chance it grabs from another recipient's main thread
    _, recipient_id, other_ids = parse_channel_topic(channel.topic)

    if recipient_id in manager.cache:
        thread = manager.cache[recipient_id]
    else:
        recipient = await manager.bot.get_or_fetch_user(recipient_id)

        other_recipients = []
        for uid in other_ids:
            try:
                other_recipient = await manager.bot.get_or_fetch_user(uid)
            except discord.NotFound:
                continue
            other_recipients.append(other_recipient)

        thread = cls(manager, recipient or recipient_id, channel, other_recipients)

    return thread

async def get_genesis_message(self) -> discord.Message:
    if self._genesis_message is None:
        async for m in self.channel.history(limit=5, oldest_first=True):
            if m.author == self.bot.user:
                if m.embeds and m.embeds[0].fields and m.embeds[0].fields[0].name == "Roles":
                    self._genesis_message = m

    return self._genesis_message

async def _close_after(self, after, closer, silent, delete_channel, message):
    await asyncio.sleep(after)
    return self.bot.loop.create_task(self._close(closer, silent, delete_channel, message, True))

async def _close(self, closer, silent=False, delete_channel=True, message=None, scheduled=False):
    if self.channel:
        self.manager.closing.add(self.channel.id)
    try:
        self.manager.cache.pop(self.id)
    except KeyError as e:
        logger.error("Thread already closed: %s.", e)
        return

    await self.cancel_closure(all=True)

    # Cancel auto closing the thread if closed by any means.

    self.bot.config["subscriptions"].pop(str(self.id), None)
    self.bot.config["notification_squad"].pop(str(self.id), None)

    # Logging
    if self.channel:
        log_data = await self.bot.api.post_log(
            self.channel.id,
            {
                "open": False,
                "title": match_title(self.channel.topic),
                "closed_at": str(discord.utils.utcnow()),
                "nsfw": self.channel.nsfw,
                "close_message": message,
                "closer": {
                    "id": str(closer.id),
                    "name": closer.name,
                    "discriminator": closer.discriminator,
                    "avatar_url": closer.display_avatar.url,
                    "mod": True,
                },
            },
        )
    else:
        log_data = None

    if isinstance(log_data, dict):
        prefix = self.bot.config["log_url_prefix"].strip("/")
        if prefix == "NONE":
            prefix = ""
        log_url = (
            f"{self.bot.config['log_url'].strip('/')}{'/' + prefix if prefix else ''}/{log_data['key']}"
        )

        if log_data["title"]:
            sneak_peak = log_data["title"]
        elif log_data["messages"]:
            content = str(log_data["messages"][0]["content"])
            sneak_peak = content.replace("\n", "")
        else:
            sneak_peak = "No content"

        if self.channel.nsfw:
            _nsfw = "NSFW-"
        else:
            _nsfw = ""

        desc = f"[`{_nsfw}{log_data['key']}`]({log_url}): "
        desc += truncate(sneak_peak, max=75 - 13)
    else:
        desc = "Could not resolve log url."
        log_url = None

    embed = discord.Embed(description=desc, color=self.bot.error_color)

    if self.recipient is not None:
        user = f"{self.recipient} (`{self.id}`)"
    else:
        user = f"`{self.id}`"

    if self.id == closer.id:
        _closer = "the Recipient"
    else:
        _closer = f"{closer} ({closer.id})"

    embed.title = user

    event = "Thread Closed as Scheduled" if scheduled else "Thread Closed"
    # embed.set_author(name=f"Event: {event}", url=log_url)
    embed.set_footer(text=f"{event} by {_closer}", icon_url=closer.display_avatar.url)
    embed.timestamp = discord.utils.utcnow()

    tasks = [self.bot.config.update()]

    if self.bot.log_channel is not None and self.channel is not None:
        if self.bot.config["show_log_url_button"]:
            view = discord.ui.View()
            view.add_item(discord.ui.Button(label="Log link", url=log_url, style=discord.ButtonStyle.url))
        else:
            view = None
        tasks.append(self.bot.log_channel.send(embed=embed, view=view))

    # Thread closed message

    embed = discord.Embed(
        title=self.bot.config["thread_close_title"],
        color=self.bot.error_color,
    )
    if self.bot.config["show_timestamp"]:
        embed.timestamp = discord.utils.utcnow()

    if not message:
        if self.id == closer.id:
            message = self.bot.config["thread_self_close_response"]
        else:
            message = self.bot.config["thread_close_response"]

    message = self.bot.formatter.format(
        message, closer=closer, loglink=log_url, logkey=log_data["key"] if log_data else None
    )

    embed.description = message
    footer = self.bot.config["thread_close_footer"]
    embed.set_footer(text=footer, icon_url=self.bot.get_guild_icon(guild=self.bot.guild, size=128))

    if not silent:
        for user in self.recipients:
            if not message:
                if user.id == closer.id:
                    message = self.bot.config["thread_self_close_response"]
                else:
                    message = self.bot.config["thread_close_response"]
                embed.description = message

            if user is not None:
                tasks.append(user.send(embed=embed))

    if delete_channel and self.channel:
        tasks.append(self.channel.delete())

    try:
        await asyncio.gather(*tasks)
    finally:
        if self.channel:
            self.manager.closing.discard(self.channel.id)

    self.bot.dispatch("thread_close", self, closer, silent, delete_channel, message, scheduled)

async def cancel_closure(self, auto_close: bool = False, all: bool = False) -> None:
    if self.close_task is not None and (not auto_close or all):
        self.close_task.cancel()
        self.close_task = None
    if self.auto_close_task is not None and (auto_close or all):
        self.auto_close_task.cancel()
        self.auto_close_task = None

    to_update = self.bot.config["closures"].pop(str(self.id), None)
    if to_update is not None:
        await self.bot.config.update()

async def find_linked_messages(
    self,
    message_id: typing.Optional[int] = None,
    either_direction: bool = False,
    message1: discord.Message = None,
    note: bool = True,
) -> typing.Tuple[discord.Message, typing.List[typing.Optional[discord.Message]]]:
    if message1 is not None:
        if not message1.embeds or not message1.embeds[0].author.url or message1.author != self.bot.user:
            raise ValueError("Malformed thread message.")

    elif message_id is not None:
        try:
            message1 = await self.channel.fetch_message(message_id)
        except discord.NotFound:
            raise ValueError("Thread message not found.")

        if not (
            message1.embeds
            and message1.embeds[0].author.url
            and message1.embeds[0].color
            and message1.author == self.bot.user
        ):
            raise ValueError("Thread message not found.")

        if message1.embeds[0].footer and "Internal Message" in message1.embeds[0].footer.text:
            if not note:
                raise ValueError("Thread message not found.")
            return message1, None

        if message1.embeds[0].color.value != self.bot.mod_color and not (
            either_direction and message1.embeds[0].color.value == self.bot.recipient_color
        ):
            raise ValueError("Thread message not found.")
    else:
        async for message1 in self.channel.history():
            if (
                message1.embeds
                and message1.embeds[0].author.url
                and message1.embeds[0].color
                and (
                    message1.embeds[0].color.value == self.bot.mod_color
                    or (either_direction and message1.embeds[0].color.value == self.bot.recipient_color)
                )
                and message1.embeds[0].author.url.split("#")[-1].isdigit()
                and message1.author == self.bot.user
            ):
                break
        else:
            raise ValueError("Thread message not found.")

    try:
        joint_id = int(message1.embeds[0].author.url.split("#")[-1])
    except ValueError:
        raise ValueError("Malformed thread message.")

    messages = [message1]
    for user in self.recipients:
        async for msg in user.history():
            if either_direction:
                if msg.id == joint_id:
                    return message1, msg

            if not (msg.embeds and msg.embeds[0].author.url):
                continue
            try:
                if int(msg.embeds[0].author.url.split("#")[-1]) == joint_id:
                    messages.append(msg)
                    break
            except ValueError:
                continue

    if len(messages) > 1:
        return messages

    raise ValueError("DM message not found.")

async def edit_message(self, message_id: typing.Optional[int], message: str) -> None:
    try:
        message1, *message2 = await self.find_linked_messages(message_id)
    except ValueError:
        logger.warning("Failed to edit message.", exc_info=True)
        raise

    embed1 = message1.embeds[0]
    embed1.description = message

    tasks = [self.bot.api.edit_message(message1.id, message), message1.edit(embed=embed1)]
    if message1.embeds[0].footer and "Persistent Internal Message" in message1.embeds[0].footer.text:
        tasks += [self.bot.api.edit_note(message1.id, message)]
    else:
        for m2 in message2:
            if m2 is not None:
                embed2 = m2.embeds[0]
                embed2.description = message
                tasks += [m2.edit(embed=embed2)]

    await asyncio.gather(*tasks)

async def delete_message(
    self, message: typing.Union[int, discord.Message] = None, note: bool = True
) -> None:
    if isinstance(message, discord.Message):
        message1, *message2 = await self.find_linked_messages(message1=message, note=note)
    else:
        message1, *message2 = await self.find_linked_messages(message, note=note)
    tasks = []

    if not isinstance(message, discord.Message):
        tasks += [message1.delete()]

    for m2 in message2:
        if m2 is not None:
            tasks += [m2.delete()]

    if message1.embeds[0].footer and "Persistent Internal Message" in message1.embeds[0].footer.text:
        tasks += [self.bot.api.delete_note(message1.id)]

    if tasks:
        await asyncio.gather(*tasks)

async def reply(
    self, message: discord.Message, anonymous: bool = False, plain: bool = False
) -> typing.Tuple[typing.List[discord.Message], discord.Message]:
    """Returns List[user_dm_msg] and thread_channel_msg"""
    if not message.content and not message.attachments and not message.stickers:
        raise MissingRequiredArgument(DummyParam("msg"))
    for guild in self.bot.guilds:
        try:
            if await self.bot.get_or_fetch_member(guild, self.id):
                break
        except discord.NotFound:
            pass
    else:
        return await message.channel.send(
            embed=discord.Embed(
                color=self.bot.error_color,
                description="Your message could not be delivered since "
                "the recipient shares no servers with the bot.",
            )
        )

    user_msg_tasks = []
    tasks = []

    for user in self.recipients:
        user_msg_tasks.append(
            self.send(
                message,
                destination=user,
                from_mod=True,
                anonymous=anonymous,
                plain=plain,
            )
        )

    try:
        user_msg = await asyncio.gather(*user_msg_tasks)
    except Exception as e:
        logger.error("Message delivery failed:", exc_info=True)
        user_msg = None
        if isinstance(e, discord.Forbidden):
            description = (
                "Your message could not be delivered as "
                "the recipient is only accepting direct "
                "messages from friends, or the bot was "
                "blocked by the recipient."
            )
        else:
            description = (
                "Your message could not be delivered due "
                "to an unknown error. Check `?debug` for "
                "more information"
            )
        msg = await message.channel.send(
            embed=discord.Embed(
                color=self.bot.error_color,
                description=description,
            )
        )
    else:
        # Send the same thing in the thread channel.
        msg = await self.send(
            message, destination=self.channel, from_mod=True, anonymous=anonymous, plain=plain
        )

        tasks.append(
            self.bot.api.append_log(
                message,
                message_id=msg.id,
                channel_id=self.channel.id,
                type_="anonymous" if anonymous else "thread_message",
            )
        )

        # Cancel closing if a thread message is sent.
        if self.close_task is not None:
            await self.cancel_closure()
            tasks.append(
                self.channel.send(
                    embed=discord.Embed(
                        color=self.bot.error_color,
                        description="Scheduled close has been cancelled.",
                    )
                )
            )

    await asyncio.gather(*tasks)
    self.bot.dispatch("thread_reply", self, True, message, anonymous, plain)
    return (user_msg, msg)  # sent_to_user, sent_to_thread_channel

async def send(
    self,
    message: discord.Message,
    destination: typing.Union[
        discord.TextChannel, discord.DMChannel, discord.User, discord.Member
    ] = None,
    from_mod: bool = False,
    note: bool = False,
    anonymous: bool = False,
    plain: bool = False,
    persistent_note: bool = False,
    thread_creation: bool = False,
) -> None:
    if not note and from_mod:
        self.bot.loop.create_task(self._restart_close_timer())  # Start or restart thread auto close

    if self.close_task is not None:
        # cancel closing if a thread message is sent.
        self.bot.loop.create_task(self.cancel_closure())
        self.bot.loop.create_task(
            self.channel.send(
                embed=discord.Embed(
                    color=self.bot.error_color,
                    description="Scheduled close has been cancelled.",
                )
            )
        )

    if not self.ready:
        await self.wait_until_ready()

    if not from_mod and not note:
        self.bot.loop.create_task(self.bot.api.append_log(message, channel_id=self.channel.id))

    destination = destination or self.channel

    if destination is None:
        logger.error("Attempted to send a message to a thread with no channel (destination is None).")
        return
    try:
        await destination.typing()
    except discord.NotFound:
        logger.warning("Channel not found when trying to send message.")
        return

    author = message.author
    member = self.bot.guild.get_member(author.id)
    if member:
        avatar_url = member.display_avatar.url
    else:
        avatar_url = author.display_avatar.url

    #  Extract content for blank/forwarded messages ---
    content = message.content
    if not content:
        # Try to extract from referenced message (replies)
        if hasattr(message, "reference") and message.reference is not None:
            try:
                ref = message.reference.resolved
                if ref and hasattr(ref, "content") and ref.content:
                    content = f"(Reply to: {ref.author}: {ref.content})"
            except Exception:
                pass
        # Try to extract from first embed's description
        if not content and message.embeds:
            first_embed = message.embeds[0]
            if hasattr(first_embed, "description") and first_embed.description:
                content = first_embed.description
        # Fallback: show something generic if still blank
        if not content:
            content = "[This is a forwarded message.]"

    embed = discord.Embed(description=content)
    if self.bot.config["show_timestamp"]:
        embed.timestamp = message.created_at

    system_avatar_url = "https://discordapp.com/assets/f78426a064bc9dd24847519259bc42af.png"

    if not note:
        if anonymous and from_mod and not isinstance(destination, discord.TextChannel):
            # Anonymously sending to the user.
            tag = self.bot.config["mod_tag"]
            if tag is None:
                tag = str(get_top_role(author, self.bot.config["use_hoisted_top_role"]))
            name = self.bot.config["anon_username"]
            if name is None:
                name = tag
            avatar_url = self.bot.config["anon_avatar_url"]
            if avatar_url is None:
                avatar_url = self.bot.get_guild_icon(guild=self.bot.guild, size=128)
            embed.set_author(
                name=name,
                icon_url=avatar_url,
                url=f"https://discordapp.com/channels/{self.bot.guild.id}#{message.id}",
            )
        else:
            # Normal message
            name = str(author)
            avatar_url = avatar_url
            embed.set_author(
                name=name,
                icon_url=avatar_url,
                url=f"https://discordapp.com/users/{author.id}#{message.id}",
            )
    else:
        # Notes are just replies with a different footer and color
        embed.set_author(
            name=str(author),
            icon_url=avatar_url,
            url=f"https://discordapp.com/users/{author.id}#{message.id}",
        )

    ext = [(a.url, a.filename, False) for a in message.attachments]

    images = []
    attachments = []
    for attachment in ext:
        if is_image_url(attachment[0]):
            images.append(attachment)
        else:
            attachments.append(attachment)

    image_urls = re.findall(
        r"http[s]?:\/\/(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*(),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+",
        message.content,
    )

    image_urls = [
        (is_image_url(url, convert_size=False), None, False)
        for url in image_urls
        if is_image_url(url, convert_size=False)
    ]
    images.extend(image_urls)

    def lottie_to_png(data):
        importer = l_importers.get("lottie")
        exporter = l_exporters.get("png")
        with io.BytesIO() as stream:
            stream.write(data)
            stream.seek(0)
            an = importer.process(stream)

        with io.BytesIO() as stream:
            exporter.process(an, stream)
            stream.seek(0)
            return stream.read()

    for i in message.stickers:
        if i.format in (
            discord.StickerFormatType.png,
            discord.StickerFormatType.apng,
            discord.StickerFormatType.gif,
        ):
            images.append(
                (f"https://media.discordapp.net/stickers/{i.id}.{i.format.file_extension}", i.name, True)
            )
        elif i.format == discord.StickerFormatType.lottie:
            # save the json lottie representation
            try:
                async with self.bot.session.get(i.url) as resp:
                    data = await resp.read()

                # convert to a png
                img_data = await self.bot.loop.run_in_executor(
                    None, functools.partial(lottie_to_png, data)
                )
                b64_data = base64.b64encode(img_data).decode()

                # upload to imgur
                async with self.bot.session.post(
                    "https://api.imgur.com/3/image",
                    headers={"Authorization": "Client-ID 50e96145ac5e085"},
                    data={"image": b64_data},
                ) as resp:
                    result = await resp.json()
                    url = result["data"]["link"]

            except Exception:
                traceback.print_exc()
                images.append((None, i.name, True))
            else:
                images.append((url, i.name, True))
        else:
            images.append((None, i.name, True))

    embedded_image = False

    prioritize_uploads = any(i[1] is not None for i in images)

    additional_images = []
    additional_count = 1

    for url, filename, is_sticker in images:
        if (
            not prioritize_uploads or ((url is None or is_image_url(url)) and filename)
        ) and not embedded_image:
            if url is not None:
                embed.set_image(url=url)
            if filename:
                if is_sticker:
                    if url is None:
                        description = f"{filename}: Unable to retrieve sticker image"
                    else:
                        description = f"[{filename}]({url})"
                    embed.add_field(name="Sticker", value=description)
                else:
                    embed.add_field(name="Image", value=f"[{filename}]({url})")
            embedded_image = True
        else:
            if note:
                color = self.bot.main_color
            elif from_mod:
                color = self.bot.mod_color
            else:
                color = self.bot.recipient_color

            img_embed = discord.Embed(color=color)

            if url is not None:
                img_embed.set_image(url=url)
                img_embed.url = url
            if filename is not None:
                img_embed.title = filename
            img_embed.set_footer(text=f"Additional Image Upload ({additional_count})")
            img_embed.timestamp = message.created_at
            additional_images.append(destination.send(embed=img_embed))
            additional_count += 1

    file_upload_count = 1

    for url, filename, _ in attachments:
        embed.add_field(name=f"File upload ({file_upload_count})", value=f"[{filename}]({url})")
        file_upload_count += 1

    if from_mod:
        embed.colour = self.bot.mod_color
        if note:
            embed.set_footer(text=f"{'Persistent' if persistent_note else ''} Internal Message")
        # Anonymous reply sent in thread channel
        elif anonymous and isinstance(destination, discord.TextChannel):
            embed.set_footer(text="Anonymous Reply")
        # Normal messages
        elif not anonymous:
            mod_tag = self.bot.config["mod_tag"]
            if mod_tag is None:
                mod_tag = str(get_top_role(message.author, self.bot.config["use_hoisted_top_role"]))
            embed.set_footer(text=mod_tag)  # Normal messages
        else:
            embed.set_footer(text=self.bot.config["anon_tag"])
    else:
        embed.set_footer(text=f"Message ID: {message.id}")
        embed.colour = self.bot.recipient_color

    if (from_mod or note) and not thread_creation:
        delete_message = not bool(message.attachments)
        if delete_message and destination == self.channel:
            try:
                await message.delete()
            except Exception as e:
                logger.warning("Cannot delete message: %s.", e)

    if (
        from_mod
        and self.bot.config["dm_disabled"] == DMDisabled.ALL_THREADS
        and destination != self.channel
    ):
        logger.info("Sending a message to %s when DM disabled is set.", self.recipient)

    try:
        await destination.typing()
    except discord.NotFound:
        logger.warning("Channel not found.")
        raise

    if not from_mod and not note:
        mentions = await self.get_notifications()
    else:
        mentions = None

    if plain:
        if from_mod and not isinstance(destination, discord.TextChannel):
            # Plain to user
            with warnings.catch_warnings():
                # Catch coroutines not awaited warning
                warnings.simplefilter("ignore")
                additional_images = []

            if embed.footer.text:
                plain_message = f"**{embed.footer.text} "
            else:
                plain_message = "**"
            plain_message += f"{embed.author.name}:** {embed.description}"
            files = []
            for i in message.attachments:
                files.append(await i.to_file())

            msg = await destination.send(plain_message, files=files)
        else:
            # Plain to mods
            embed.set_footer(text="[PLAIN] " + embed.footer.text)
            msg = await destination.send(mentions, embed=embed)

    else:
        msg = await destination.send(mentions, embed=embed)

    if additional_images:
        self.ready = False
        await asyncio.gather(*additional_images)
        self.ready = True

    return msg

async def populate_cache(self) -> None:
    for channel in self.bot.modmail_guild.text_channels:
        await self.find(channel=channel)

async def find(
    self,
    *,
    recipient: typing.Union[discord.Member, discord.User] = None,
    channel: discord.TextChannel = None,
    recipient_id: int = None,
) -> typing.Optional[Thread]:
    """Finds a thread from cache or from discord channel topics."""
    if recipient is None and channel is not None and isinstance(channel, discord.TextChannel):
        if channel.id in self.closing:
            return None
        thread = await self._find_from_channel(channel)
        if thread is None:
            user_id, thread = next(
                ((k, v) for k, v in self.cache.items() if v.channel == channel), (-1, None)
            )
            if thread is not None:
                logger.debug("Found thread with tempered ID.")
                await channel.edit(topic=f"User ID: {user_id}")
        return thread

    if recipient:
        recipient_id = recipient.id

    thread = self.cache.get(recipient_id)
    if thread is not None:
        try:
            await thread.wait_until_ready()
        except asyncio.CancelledError:
            logger.warning("Thread for %s cancelled.", recipient)
            return thread
        else:
            # If the thread is snoozed (channel is None), return it for restoration
            if thread.cancelled:
                thread = None
    else:

        def check(topic):
            _, user_id, other_ids = parse_channel_topic(topic)
            return recipient_id == user_id or recipient_id in other_ids

        channel = discord.utils.find(
            lambda x: (check(x.topic)) if x.topic else False,
            self.bot.modmail_guild.text_channels,
        )

        if channel:
            thread = await Thread.from_channel(self, channel)
            if thread.recipient:
                # only save if data is valid.
                # also the recipient_id here could belong to other recipient,
                # it would be wrong if we set it as the dict key,
                # so we use the thread id instead
                self.cache[thread.id] = thread
            thread.ready = True

    if thread and recipient_id not in [x.id for x in thread.recipients]:
        self.cache.pop(recipient_id)
        thread = None

    return thread

async def _find_from_channel(self, channel):
    """
    Tries to find a thread from a channel channel topic,
    if channel topic doesnt exist for some reason, falls back to
    searching channel history for genesis embed and
    extracts user_id from that.
    """

    if not channel.topic:
        return None

    _, user_id, other_ids = parse_channel_topic(channel.topic)

    if user_id == -1:
        return None

    if user_id in self.cache:
        return self.cache[user_id]

    try:
        recipient = await self.bot.get_or_fetch_user(user_id)
    except discord.NotFound:
        recipient = None

    other_recipients = []
    for uid in other_ids:
        try:
            other_recipient = await self.bot.get_or_fetch_user(uid)
        except discord.NotFound:
            continue
        other_recipients.append(other_recipient)

    if recipient is None:
        thread = Thread(self, user_id, channel, other_recipients)
    else:
        self.cache[user_id] = thread = Thread(self, recipient, channel, other_recipients)
    thread.ready = True

    return thread

async def create(
    self,
    recipient: typing.Union[discord.Member, discord.User],
    *,
    message: discord.Message = None,
    creator: typing.Union[discord.Member, discord.User] = None,
    category: discord.CategoryChannel = None,
    manual_trigger: bool = True,
) -> Thread:
    """Creates a Modmail thread"""

    # Minimum character check
    min_chars = self.bot.config.get("thread_min_characters")
    if min_chars is None:
        min_chars = 0
    try:
        min_chars = int(min_chars)
    except ValueError:
        min_chars = 0
    if min_chars > 0 and message is not None and message.content is not None:
        if len(message.content.strip()) < min_chars:
            embed = discord.Embed(
                title=self.bot.config["thread_min_characters_title"],
                description=self.bot.config["thread_min_characters_response"].replace(
                    "{min_characters}", str(min_chars)
                ),
                color=self.bot.error_color,
            )
            embed.set_footer(
                text=self.bot.config["thread_min_characters_footer"].replace(
                    "{min_characters}", str(min_chars)
                )
            )
            await message.channel.send(embed=embed)
            thread = Thread(self, recipient)
            thread.cancelled = True
            return thread

    # checks for existing thread in cache
    thread = self.cache.get(recipient.id)
    if thread:
        try:
            await thread.wait_until_ready()
        except asyncio.CancelledError:
            logger.warning("Thread for %s cancelled, abort creating.", recipient)
            return thread
        else:
            if thread.channel and self.bot.get_channel(thread.channel.id):
                logger.warning("Found an existing thread for %s, abort creating.", recipient)
                return thread
            logger.warning("Found an existing thread for %s, closing previous thread.", recipient)
            self.bot.loop.create_task(
                thread.close(closer=self.bot.user, silent=True, delete_channel=False)
            )

    thread = Thread(self, recipient)

    self.cache[recipient.id] = thread

    if (message or not manual_trigger) and self.bot.config["confirm_thread_creation"]:
        if not manual_trigger:
            destination = recipient
        else:
            destination = message.channel
        view = ConfirmThreadCreationView()
        view.add_item(AcceptButton(self.bot.config["confirm_thread_creation_accept"]))
        view.add_item(DenyButton(self.bot.config["confirm_thread_creation_deny"]))
        confirm = await destination.send(
            embed=discord.Embed(
                title=self.bot.config["confirm_thread_creation_title"],
                description=self.bot.config["confirm_thread_response"],
                color=self.bot.main_color,
            ),
            view=view,
        )
        await view.wait()
        if view.value is None:
            thread.cancelled = True
            self.bot.loop.create_task(
                destination.send(
                    embed=discord.Embed(
                        title=self.bot.config["thread_cancelled"],
                        description="Timed out",
                        color=self.bot.error_color,
                    )
                )
            )
            await confirm.edit(view=None)
        if view.value is False:
            thread.cancelled = True
            self.bot.loop.create_task(
                destination.send(
                    embed=discord.Embed(
                        title=self.bot.config["thread_cancelled"], color=self.bot.error_color
                    )
                )
            )
        if thread.cancelled:
            del self.cache[recipient.id]
            return thread

    self.bot.loop.create_task(thread.setup(creator=creator, category=category, initial_message=message))
    return thread

def human_timedelta(
    dt: datetime.datetime,
    *,
    source: Optional[datetime.datetime] = None,
    accuracy: Optional[int] = 3,
    brief: bool = False,
    suffix: bool = True,
) -> str:
    now = source or datetime.datetime.now(datetime.timezone.utc)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)

    if now.tzinfo is None:
        now = now.replace(tzinfo=datetime.timezone.utc)

    # Microsecond free zone
    now = now.replace(microsecond=0)
    dt = dt.replace(microsecond=0)

    # This implementation uses relativedelta instead of the much more obvious
    # divmod approach with seconds because the seconds approach is not entirely
    # accurate once you go over 1 week in terms of accuracy since you have to
    # hardcode a month as 30 or 31 days.
    # A query like "11 months" can be interpreted as "!1 months and 6 days"
    if dt > now:
        delta = relativedelta(dt, now)
        output_suffix = ""
    else:
        delta = relativedelta(now, dt)
        output_suffix = " ago" if suffix else ""

    attrs = [
        ("year", "y"),
        ("month", "mo"),
        ("day", "d"),
        ("hour", "h"),
        ("minute", "m"),
        ("second", "s"),
    ]

    output = []
    for attr, brief_attr in attrs:
        elem = getattr(delta, attr + "s")
        if not elem:
            continue

        if attr == "day":
            weeks = delta.weeks
            if weeks:
                elem -= weeks * 7
                if not brief:
                    output.append(format(plural(weeks), "week"))
                else:
                    output.append(f"{weeks}w")

        if elem <= 0:
            continue

        if brief:
            output.append(f"{elem}{brief_attr}")
        else:
            output.append(format(plural(elem), attr))

    if accuracy is not None:
        output = output[:accuracy]

    if len(output) == 0:
        return "now"
    else:
        if not brief:
            return human_join(output, final="and") + output_suffix
        else:
            return " ".join(output) + output_suffix

def human_timedelta(
    dt: datetime.datetime,
    *,
    source: Optional[datetime.datetime] = None,
    accuracy: Optional[int] = 3,
    brief: bool = False,
    suffix: bool = True,
) -> str:
    now = source or datetime.datetime.now(datetime.timezone.utc)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)

    if now.tzinfo is None:
        now = now.replace(tzinfo=datetime.timezone.utc)

    # Microsecond free zone
    now = now.replace(microsecond=0)
    dt = dt.replace(microsecond=0)

    # This implementation uses relativedelta instead of the much more obvious
    # divmod approach with seconds because the seconds approach is not entirely
    # accurate once you go over 1 week in terms of accuracy since you have to
    # hardcode a month as 30 or 31 days.
    # A query like "11 months" can be interpreted as "!1 months and 6 days"
    if dt > now:
        delta = relativedelta(dt, now)
        output_suffix = ""
    else:
        delta = relativedelta(now, dt)
        output_suffix = " ago" if suffix else ""

    attrs = [
        ("year", "y"),
        ("month", "mo"),
        ("day", "d"),
        ("hour", "h"),
        ("minute", "m"),
        ("second", "s"),
    ]

    output = []
    for attr, brief_attr in attrs:
        elem = getattr(delta, attr + "s")
        if not elem:
            continue

        if attr == "day":
            weeks = delta.weeks
            if weeks:
                elem -= weeks * 7
                if not brief:
                    output.append(format(plural(weeks), "week"))
                else:
                    output.append(f"{weeks}w")

        if elem <= 0:
            continue

        if brief:
            output.append(f"{elem}{brief_attr}")
        else:
            output.append(format(plural(elem), attr))

    if accuracy is not None:
        output = output[:accuracy]

    if len(output) == 0:
        return "now"
    else:
        if not brief:
            return human_join(output, final="and") + output_suffix
        else:
            return " ".join(output) + output_suffix

class plural:
    """https://github.com/Rapptz/RoboDanny/blob/bf7d4226350dff26df4981dd53134eeb2aceeb87/cogs/utils/formats.py#L8-L18"""

    def __init__(self, value: int):
        self.value: int = value

    def __format__(self, format_spec: str) -> str:
        v = self.value
        singular, sep, plural = format_spec.partition("|")
        plural = plural or f"{singular}s"
        if abs(v) != 1:
            return f"{v} {plural}"
        return f"{v} {singular}"

class ShortTime:
    compiled = re.compile(
        """
           (?:(?P<years>[0-9])(?:years?|y))?             # e.g. 2y
           (?:(?P<months>[0-9]{1,2})(?:months?|mo))?     # e.g. 2months
           (?:(?P<weeks>[0-9]{1,4})(?:weeks?|w))?        # e.g. 10w
           (?:(?P<days>[0-9]{1,5})(?:days?|d))?          # e.g. 14d
           (?:(?P<hours>[0-9]{1,5})(?:hours?|h))?        # e.g. 12h
           (?:(?P<minutes>[0-9]{1,5})(?:minutes?|m))?    # e.g. 10m
           (?:(?P<seconds>[0-9]{1,5})(?:seconds?|s))?    # e.g. 15s
        """,
        re.VERBOSE,
    )

    discord_fmt = re.compile(r"<t:(?P<ts>[0-9]+)(?:\:?[RFfDdTt])?>")

    dt: datetime.datetime

    def __init__(self, argument: str, *, now: Optional[datetime.datetime] = None):
        match = self.compiled.fullmatch(argument)
        if match is None or not match.group(0):
            match = self.discord_fmt.fullmatch(argument)
            if match is not None:
                self.dt = datetime.datetime.utcfromtimestamp(int(match.group("ts")), tz=datetime.timezone.utc)
                return
            else:
                raise commands.BadArgument("invalid time provided")

        data = {k: int(v) for k, v in match.groupdict(default=0).items()}
        now = now or datetime.datetime.now(datetime.timezone.utc)
        self.dt = now + relativedelta(**data)

    @classmethod
    async def convert(cls, ctx: Context, argument: str) -> Self:
        return cls(argument, now=ctx.message.created_at)

class HumanTime:
    calendar = pdt.Calendar(version=pdt.VERSION_CONTEXT_STYLE)

    def __init__(self, argument: str, *, now: Optional[datetime.datetime] = None):
        now = now or datetime.datetime.utcnow()
        dt, status = self.calendar.parseDT(argument, sourceTime=now)
        if not status.hasDateOrTime:
            raise commands.BadArgument('invalid time provided, try e.g. "tomorrow" or "3 days"')

        if not status.hasTime:
            # replace it with the current time
            dt = dt.replace(hour=now.hour, minute=now.minute, second=now.second, microsecond=now.microsecond)

        self.dt: datetime.datetime = dt
        self._past: bool = dt < now

    @classmethod
    async def convert(cls, ctx: Context, argument: str) -> Self:
        return cls(argument, now=ctx.message.created_at)

class Time(HumanTime):
    def __init__(self, argument: str, *, now: Optional[datetime.datetime] = None):
        try:
            o = ShortTime(argument, now=now)
        except Exception:
            super().__init__(argument)
        else:
            self.dt = o.dt
            self._past = False

class FutureTime(Time):
    def __init__(self, argument: str, *, now: Optional[datetime.datetime] = None):
        super().__init__(argument, now=now)

        if self._past:
            raise commands.BadArgument("this time is in the past")

class TimeTransformer(app_commands.Transformer):
    async def transform(self, interaction, value: str) -> datetime.datetime:
        now = interaction.created_at
        try:
            short = ShortTime(value, now=now)
        except commands.BadArgument:
            try:
                human = FutureTime(value, now=now)
            except commands.BadArgument as e:
                raise BadTimeTransform(str(e)) from None
            else:
                return human.dt
        else:
            return short.dt

class UserFriendlyTime(commands.Converter):
    """That way quotes aren't absolutely necessary."""

    def __init__(
        self,
        converter: Optional[Union[type[commands.Converter], commands.Converter]] = None,
        *,
        default: Any = None,
    ):
        if isinstance(converter, type) and issubclass(converter, commands.Converter):
            converter = converter()

        if converter is not None and not isinstance(converter, commands.Converter):
            raise TypeError("commands.Converter subclass necessary.")

        self.converter: commands.Converter = converter  # type: ignore  # It doesn't understand this narrowing
        self.default: Any = default

    async def convert(self, ctx: Context, argument: str, *, now=None) -> FriendlyTimeResult:
        calendar = HumanTime.calendar
        regex = ShortTime.compiled
        if now is None:
            now = ctx.message.created_at

        match = regex.match(argument)
        if match is not None and match.group(0):
            data = {k: int(v) for k, v in match.groupdict(default=0).items()}
            remaining = argument[match.end() :].strip()
            result = FriendlyTimeResult(now + relativedelta(**data), now)
            await result.ensure_constraints(ctx, self, now, remaining)
            return result

        if match is None or not match.group(0):
            match = ShortTime.discord_fmt.match(argument)
            if match is not None:
                result = FriendlyTimeResult(
                    datetime.datetime.utcfromtimestamp(int(match.group("ts")), now, tz=datetime.timezone.utc)
                )
                remaining = argument[match.end() :].strip()
                await result.ensure_constraints(ctx, self, now, remaining)
                return result

        # apparently nlp does not like "from now"
        # it likes "from x" in other cases though so let me handle the 'now' case
        if argument.endswith("from now"):
            argument = argument[:-8].strip()

        if argument[0:2] == "me":
            # starts with "me to", "me in", or "me at "
            if argument[0:6] in ("me to ", "me in ", "me at "):
                argument = argument[6:]

        elements = calendar.nlp(argument, sourceTime=now)
        if elements is None or len(elements) == 0:
            # CHANGE
            result = FriendlyTimeResult(now)
            await result.ensure_constraints(ctx, self, now, argument)
            return result

        # handle the following cases:
        # "date time" foo
        # date time foo
        # foo date time

        # first the first two cases:
        dt, status, begin, end, dt_string = elements[0]

        if not status.hasDateOrTime:
            raise commands.BadArgument('Invalid time provided, try e.g. "tomorrow" or "3 days".')

        if begin not in (0, 1) and end != len(argument):
            raise commands.BadArgument(
                "Time is either in an inappropriate location, which "
                "must be either at the end or beginning of your input, "
                "or I just flat out did not understand what you meant. Sorry."
            )

        if not status.hasTime:
            # replace it with the current time
            dt = dt.replace(hour=now.hour, minute=now.minute, second=now.second, microsecond=now.microsecond)

        # if midnight is provided, just default to next day
        if status.accuracy == pdt.pdtContext.ACU_HALFDAY:
            dt = dt.replace(day=now.day + 1)

        result = FriendlyTimeResult(dt.replace(tzinfo=datetime.timezone.utc), now)
        remaining = ""

        if begin in (0, 1):
            if begin == 1:
                # check if it's quoted:
                if argument[0] != '"':
                    raise commands.BadArgument("Expected quote before time input...")

                if not (end < len(argument) and argument[end] == '"'):
                    raise commands.BadArgument("If the time is quoted, you must unquote it.")

                remaining = argument[end + 1 :].lstrip(" ,.!")
            else:
                remaining = argument[end:].lstrip(" ,.!")
        elif len(argument) == end:
            remaining = argument[:begin].strip()

        await result.ensure_constraints(ctx, self, now, remaining)
        return result

def strtobool(val):
    if isinstance(val, bool):
        return val
    try:
        return _stb(str(val))
    except ValueError:
        val = val.lower()
        if val == "enable":
            return 1
        if val == "disable":
            return 0
        raise

def parse_image_url(url: str, *, convert_size=True) -> str:
    """
    Convert the image URL into a sized Discord avatar.

    Parameters
    ----------
    url : str
        The URL to convert.

    Returns
    -------
    str
        The converted URL, or '' if the URL isn't in the proper format.
    """
    types = [".png", ".jpg", ".gif", ".jpeg", ".webp"]
    url = parse.urlsplit(url)

    if any(url.path.lower().endswith(i) for i in types):
        if convert_size:
            return parse.urlunsplit((*url[:3], "size=128", url[-1]))
        else:
            return parse.urlunsplit(url)
    return ""

def trigger_typing(func):
    @functools.wraps(func)
    async def wrapper(self, ctx: commands.Context, *args, **kwargs):
        await ctx.typing()
        return await func(self, ctx, *args, **kwargs)

    return wrapper

def get_top_role(member: discord.Member, hoisted=True):
    roles = sorted(member.roles, key=lambda r: r.position, reverse=True)
    for role in roles:
        if not hoisted:
            return role
        if role.hoist:
            return role

async def query(
    self,
    sql: str,
    params: dict[str, Any] | None = None,
    multirows: bool = False,
    with_age: bool = False,
    graph_name: str | None = None,
) -> dict[str, Any] | None | list[dict[str, Any]]:
    async with self.pool.acquire() as connection:  # type: ignore
        if with_age and graph_name:
            await self.configure_age(connection, graph_name)  # type: ignore
        elif with_age and not graph_name:
            raise ValueError("Graph name is required when with_age is True")

        try:
            if params:
                rows = await connection.fetch(sql, *params.values())
            else:
                rows = await connection.fetch(sql)

            if multirows:
                if rows:
                    columns = [col for col in rows[0].keys()]
                    data = [dict(zip(columns, row)) for row in rows]
                else:
                    data = []
            else:
                if rows:
                    columns = rows[0].keys()
                    data = dict(zip(columns, rows[0]))
                else:
                    data = None

            return data
        except Exception as e:
            logger.error(f"PostgreSQL database, error:{e}")
            raise

async def execute(
    self,
    sql: str,
    data: dict[str, Any] | None = None,
    upsert: bool = False,
    ignore_if_exists: bool = False,
    with_age: bool = False,
    graph_name: str | None = None,
):
    try:
        async with self.pool.acquire() as connection:  # type: ignore
            if with_age and graph_name:
                await self.configure_age(connection, graph_name)
            elif with_age and not graph_name:
                raise ValueError("Graph name is required when with_age is True")

            if data is None:
                await connection.execute(sql)
            else:
                await connection.execute(sql, *data.values())
    except (
        asyncpg.exceptions.UniqueViolationError,
        asyncpg.exceptions.DuplicateTableError,
        asyncpg.exceptions.DuplicateObjectError,  # Catch "already exists" error
        asyncpg.exceptions.InvalidSchemaNameError,  # Also catch for AGE extension "already exists"
    ) as e:
        if ignore_if_exists:
            # If the flag is set, just ignore these specific errors
            pass
        elif upsert:
            print("Key value duplicate, but upsert succeeded.")
        else:
            logger.error(f"Upsert error: {e}")
    except Exception as e:
        logger.error(f"PostgreSQL database,\nsql:{sql},\ndata:{data},\nerror:{e}")
        raise

async def get_by_ids(self, ids: list[str]) -> list[dict[str, Any]]:
    """Get data by ids"""
    sql = SQL_TEMPLATES["get_by_ids_" + self.namespace].format(
        ids=",".join([f"'{id}'" for id in ids])
    )
    params = {"workspace": self.workspace}
    results = await self.db.query(sql, params, multirows=True)

    if results and is_namespace(self.namespace, NameSpace.KV_STORE_TEXT_CHUNKS):
        # Parse llm_cache_list JSON string back to list for each result
        for result in results:
            llm_cache_list = result.get("llm_cache_list", [])
            if isinstance(llm_cache_list, str):
                try:
                    llm_cache_list = json.loads(llm_cache_list)
                except json.JSONDecodeError:
                    llm_cache_list = []
            result["llm_cache_list"] = llm_cache_list
            create_time = result.get("create_time", 0)
            update_time = result.get("update_time", 0)
            result["create_time"] = create_time
            result["update_time"] = create_time if update_time == 0 else update_time

    # Special handling for LLM cache to ensure compatibility with _get_cached_extraction_results
    if results and is_namespace(
        self.namespace, NameSpace.KV_STORE_LLM_RESPONSE_CACHE
    ):
        processed_results = []
        for row in results:
            create_time = row.get("create_time", 0)
            update_time = row.get("update_time", 0)
            # Parse queryparam JSON string back to dict
            queryparam = row.get("queryparam")
            if isinstance(queryparam, str):
                try:
                    queryparam = json.loads(queryparam)
                except json.JSONDecodeError:
                    queryparam = None
            # Map field names for compatibility (mode field removed)
            processed_row = {
                **row,
                "return": row.get("return_value", ""),
                "cache_type": row.get("cache_type"),
                "original_prompt": row.get("original_prompt", ""),
                "chunk_id": row.get("chunk_id"),
                "queryparam": queryparam,
                "create_time": create_time,
                "update_time": create_time if update_time == 0 else update_time,
            }
            processed_results.append(processed_row)
        return processed_results

    # Special handling for FULL_ENTITIES namespace
    if results and is_namespace(self.namespace, NameSpace.KV_STORE_FULL_ENTITIES):
        for result in results:
            # Parse entity_names JSON string back to list
            entity_names = result.get("entity_names", [])
            if isinstance(entity_names, str):
                try:
                    entity_names = json.loads(entity_names)
                except json.JSONDecodeError:
                    entity_names = []
            result["entity_names"] = entity_names
            create_time = result.get("create_time", 0)
            update_time = result.get("update_time", 0)
            result["create_time"] = create_time
            result["update_time"] = create_time if update_time == 0 else update_time

    # Special handling for FULL_RELATIONS namespace
    if results and is_namespace(self.namespace, NameSpace.KV_STORE_FULL_RELATIONS):
        for result in results:
            # Parse relation_pairs JSON string back to list
            relation_pairs = result.get("relation_pairs", [])
            if isinstance(relation_pairs, str):
                try:
                    relation_pairs = json.loads(relation_pairs)
                except json.JSONDecodeError:
                    relation_pairs = []
            result["relation_pairs"] = relation_pairs
            create_time = result.get("create_time", 0)
            update_time = result.get("update_time", 0)
            result["create_time"] = create_time
            result["update_time"] = create_time if update_time == 0 else update_time

    return results if results else []

async def filter_keys(self, keys: set[str]) -> set[str]:
    """Filter out duplicated content"""
    sql = SQL_TEMPLATES["filter_keys"].format(
        table_name=namespace_to_table_name(self.namespace),
        ids=",".join([f"'{id}'" for id in keys]),
    )
    params = {"workspace": self.workspace}
    try:
        res = await self.db.query(sql, params, multirows=True)
        if res:
            exist_keys = [key["id"] for key in res]
        else:
            exist_keys = []
        new_keys = set([s for s in keys if s not in exist_keys])
        return new_keys
    except Exception as e:
        logger.error(
            f"[{self.workspace}] PostgreSQL database,\nsql:{sql},\nparams:{params},\nerror:{e}"
        )
        raise

async def upsert(self, data: dict[str, dict[str, Any]]) -> None:
    logger.debug(f"[{self.workspace}] Inserting {len(data)} to {self.namespace}")
    if not data:
        return

    if is_namespace(self.namespace, NameSpace.KV_STORE_TEXT_CHUNKS):
        # Get current UTC time and convert to naive datetime for database storage
        current_time = datetime.datetime.now(timezone.utc).replace(tzinfo=None)
        for k, v in data.items():
            upsert_sql = SQL_TEMPLATES["upsert_text_chunk"]
            _data = {
                "workspace": self.workspace,
                "id": k,
                "tokens": v["tokens"],
                "chunk_order_index": v["chunk_order_index"],
                "full_doc_id": v["full_doc_id"],
                "content": v["content"],
                "file_path": v["file_path"],
                "llm_cache_list": json.dumps(v.get("llm_cache_list", [])),
                "create_time": current_time,
                "update_time": current_time,
            }
            await self.db.execute(upsert_sql, _data)
    elif is_namespace(self.namespace, NameSpace.KV_STORE_FULL_DOCS):
        for k, v in data.items():
            upsert_sql = SQL_TEMPLATES["upsert_doc_full"]
            _data = {
                "id": k,
                "content": v["content"],
                "workspace": self.workspace,
            }
            await self.db.execute(upsert_sql, _data)
    elif is_namespace(self.namespace, NameSpace.KV_STORE_LLM_RESPONSE_CACHE):
        for k, v in data.items():
            upsert_sql = SQL_TEMPLATES["upsert_llm_response_cache"]
            _data = {
                "workspace": self.workspace,
                "id": k,  # Use flattened key as id
                "original_prompt": v["original_prompt"],
                "return_value": v["return"],
                "chunk_id": v.get("chunk_id"),
                "cache_type": v.get(
                    "cache_type", "extract"
                ),  # Get cache_type from data
                "queryparam": json.dumps(v.get("queryparam"))
                if v.get("queryparam")
                else None,
            }

            await self.db.execute(upsert_sql, _data)
    elif is_namespace(self.namespace, NameSpace.KV_STORE_FULL_ENTITIES):
        # Get current UTC time and convert to naive datetime for database storage
        current_time = datetime.datetime.now(timezone.utc).replace(tzinfo=None)
        for k, v in data.items():
            upsert_sql = SQL_TEMPLATES["upsert_full_entities"]
            _data = {
                "workspace": self.workspace,
                "id": k,
                "entity_names": json.dumps(v["entity_names"]),
                "count": v["count"],
                "create_time": current_time,
                "update_time": current_time,
            }
            await self.db.execute(upsert_sql, _data)
    elif is_namespace(self.namespace, NameSpace.KV_STORE_FULL_RELATIONS):
        # Get current UTC time and convert to naive datetime for database storage
        current_time = datetime.datetime.now(timezone.utc).replace(tzinfo=None)
        for k, v in data.items():
            upsert_sql = SQL_TEMPLATES["upsert_full_relations"]
            _data = {
                "workspace": self.workspace,
                "id": k,
                "relation_pairs": json.dumps(v["relation_pairs"]),
                "count": v["count"],
                "create_time": current_time,
                "update_time": current_time,
            }
            await self.db.execute(upsert_sql, _data)

async def drop(self) -> dict[str, str]:
    """Drop the storage"""
    async with get_storage_lock():
        try:
            table_name = namespace_to_table_name(self.namespace)
            if not table_name:
                return {
                    "status": "error",
                    "message": f"Unknown namespace: {self.namespace}",
                }

            drop_sql = SQL_TEMPLATES["drop_specifiy_table_workspace"].format(
                table_name=table_name
            )
            await self.db.execute(drop_sql, {"workspace": self.workspace})
            return {"status": "success", "message": "data dropped"}
        except Exception as e:
            return {"status": "error", "message": str(e)}

def __post_init__(self):
    self._max_batch_size = self.global_config["embedding_batch_num"]
    config = self.global_config.get("vector_db_storage_cls_kwargs", {})
    cosine_threshold = config.get("cosine_better_than_threshold")
    if cosine_threshold is None:
        raise ValueError(
            "cosine_better_than_threshold must be specified in vector_db_storage_cls_kwargs"
        )
    self.cosine_better_than_threshold = cosine_threshold

def _upsert_chunks(
    self, item: dict[str, Any], current_time: datetime.datetime
) -> tuple[str, dict[str, Any]]:
    try:
        upsert_sql = SQL_TEMPLATES["upsert_chunk"]
        data: dict[str, Any] = {
            "workspace": self.workspace,
            "id": item["__id__"],
            "tokens": item["tokens"],
            "chunk_order_index": item["chunk_order_index"],
            "full_doc_id": item["full_doc_id"],
            "content": item["content"],
            "content_vector": json.dumps(item["__vector__"].tolist()),
            "file_path": item["file_path"],
            "create_time": current_time,
            "update_time": current_time,
        }
    except Exception as e:
        logger.error(
            f"[{self.workspace}] Error to prepare upsert,\nsql: {e}\nitem: {item}"
        )
        raise

    return upsert_sql, data

async def delete(self, ids: list[str]) -> None:
    """Delete vectors with specified IDs from the storage.

    Args:
        ids: List of vector IDs to be deleted
    """
    if not ids:
        return

    table_name = namespace_to_table_name(self.namespace)
    if not table_name:
        logger.error(
            f"[{self.workspace}] Unknown namespace for vector deletion: {self.namespace}"
        )
        return

    delete_sql = f"DELETE FROM {table_name} WHERE workspace=$1 AND id = ANY($2)"

    try:
        await self.db.execute(delete_sql, {"workspace": self.workspace, "ids": ids})
        logger.debug(
            f"[{self.workspace}] Successfully deleted {len(ids)} vectors from {self.namespace}"
        )
    except Exception as e:
        logger.error(
            f"[{self.workspace}] Error while deleting vectors from {self.namespace}: {e}"
        )

async def delete_entity_relation(self, entity_name: str) -> None:
    """Delete all relations associated with an entity.

    Args:
        entity_name: The name of the entity whose relations should be deleted
    """
    try:
        # Delete relations where the entity is either the source or target
        delete_sql = """DELETE FROM LIGHTRAG_VDB_RELATION
                        WHERE workspace=$1 AND (source_id=$2 OR target_id=$2)"""

        await self.db.execute(
            delete_sql, {"workspace": self.workspace, "entity_name": entity_name}
        )
        logger.debug(
            f"[{self.workspace}] Successfully deleted relations for entity {entity_name}"
        )
    except Exception as e:
        logger.error(
            f"[{self.workspace}] Error deleting relations for entity {entity_name}: {e}"
        )

async def get_by_id(self, id: str) -> dict[str, Any] | None:
    """Get vector data by its ID

    Args:
        id: The unique identifier of the vector

    Returns:
        The vector data if found, or None if not found
    """
    table_name = namespace_to_table_name(self.namespace)
    if not table_name:
        logger.error(
            f"[{self.workspace}] Unknown namespace for ID lookup: {self.namespace}"
        )
        return None

    query = f"SELECT *, EXTRACT(EPOCH FROM create_time)::BIGINT as created_at FROM {table_name} WHERE workspace=$1 AND id=$2"
    params = {"workspace": self.workspace, "id": id}

    try:
        result = await self.db.query(query, params)
        if result:
            return dict(result)
        return None
    except Exception as e:
        logger.error(
            f"[{self.workspace}] Error retrieving vector data for ID {id}: {e}"
        )
        return None

async def get_vectors_by_ids(self, ids: list[str]) -> dict[str, list[float]]:
    """Get vectors by their IDs, returning only ID and vector data for efficiency

    Args:
        ids: List of unique identifiers

    Returns:
        Dictionary mapping IDs to their vector embeddings
        Format: {id: [vector_values], ...}
    """
    if not ids:
        return {}

    table_name = namespace_to_table_name(self.namespace)
    if not table_name:
        logger.error(
            f"[{self.workspace}] Unknown namespace for vector lookup: {self.namespace}"
        )
        return {}

    ids_str = ",".join([f"'{id}'" for id in ids])
    query = f"SELECT id, content_vector FROM {table_name} WHERE workspace=$1 AND id IN ({ids_str})"
    params = {"workspace": self.workspace}

    try:
        results = await self.db.query(query, params, multirows=True)
        vectors_dict = {}

        for result in results:
            if result and "content_vector" in result and "id" in result:
                try:
                    # Parse JSON string to get vector as list of floats
                    vector_data = json.loads(result["content_vector"])
                    if isinstance(vector_data, list):
                        vectors_dict[result["id"]] = vector_data
                except (json.JSONDecodeError, TypeError) as e:
                    logger.warning(
                        f"[{self.workspace}] Failed to parse vector data for ID {result['id']}: {e}"
                    )

        return vectors_dict
    except Exception as e:
        logger.error(
            f"[{self.workspace}] Error retrieving vectors by IDs from {self.namespace}: {e}"
        )
        return {}

