def _has_ipv6(host: str):
    sock = None
    has_ipv6 = False
    if socket.has_ipv6:
        try:
            sock = socket.socket(socket.AF_INET6)
            sock.bind((host, 0))
            has_ipv6 = True
        except Exception:  # pragma: no cover
            pass
    if sock:
        sock.close()
    return has_ipv6

def auto_loop_factory(use_subprocess: bool = False) -> Callable[[], asyncio.AbstractEventLoop]:
    try:
        if sys.platform == "win32":  # pragma: py-win32
            from uvicorn.loops.winloop import winloop_loop_factory as loop_factory
        else:  # pragma: py-not-win32
            from uvicorn.loops.uvloop import uvloop_loop_factory as loop_factory
    except ImportError:  # pragma: no cover
        from uvicorn.loops.asyncio import asyncio_loop_factory as loop_factory
    return loop_factory(use_subprocess=use_subprocess)

def process_frames() -> ErrorCode:
	source_audio_path = get_first(filter_audio_paths(state_manager.get_item('source_paths')))
	audio_frame_total = count_audio_frame_total(source_audio_path, 25.0)
	output_video_fps = state_manager.get_item('output_video_fps')
	temp_frame_paths = get_temp_frame_sequence_paths(state_manager.get_item('target_path'), audio_frame_total, '%08d')

	if temp_frame_paths:
		with tqdm(total = len(temp_frame_paths), desc = translator.get('processing'), unit = 'frame', ascii = ' =', disable = state_manager.get_item('log_level') in [ 'warn', 'error' ]) as progress:
			progress.set_postfix(execution_providers = state_manager.get_item('execution_providers'))

			with ThreadPoolExecutor(max_workers = state_manager.get_item('execution_thread_count')) as executor:
				futures = []

				for frame_number, temp_frame_path in enumerate(temp_frame_paths):
					future = executor.submit(conditional_process_temp_frame, temp_frame_path, frame_number, output_video_fps)
					futures.append(future)

				for future in as_completed(futures):
					if is_process_stopping():
						for __future__ in futures:
							__future__.cancel()

					if not future.cancelled():
						future.result()
						progress.update()

		for processor_module in get_processors_modules(state_manager.get_item('processors')):
			processor_module.post_process()

		if is_process_stopping():
			return 4
	else:
		logger.error(translator.get('temp_frames_not_found'), __name__)
		return 1
	return 0

def conditional_process_temp_frame(temp_frame_path : str, frame_number : int, output_video_fps : float) -> bool:
	source_vision_frames = read_static_images(state_manager.get_item('source_paths'))
	source_audio_path = get_first(filter_audio_paths(state_manager.get_item('source_paths')))
	target_vision_frame = read_static_image(temp_frame_path, 'rgba')
	temp_vision_frame = target_vision_frame.copy()
	temp_vision_mask = extract_vision_mask(temp_vision_frame)

	if is_video(state_manager.get_item('target_path')):
		reference_vision_frame = read_static_video_frame(state_manager.get_item('target_path'), state_manager.get_item('reference_frame_number'))
	else:
		temp_image_path = get_temp_file_path(state_manager.get_item('target_path'))
		reference_vision_frame = read_static_image(temp_image_path)

	source_audio_frame = get_audio_frame(source_audio_path, output_video_fps, frame_number)
	source_voice_frame = get_voice_frame(source_audio_path, output_video_fps, frame_number)

	if not numpy.any(source_audio_frame):
		source_audio_frame = create_empty_audio_frame()
	if not numpy.any(source_voice_frame):
		source_voice_frame = create_empty_audio_frame()

	for processor_module in get_processors_modules(state_manager.get_item('processors')):
		temp_vision_frame, temp_vision_mask = processor_module.process_frame(
		{
			'reference_vision_frame': reference_vision_frame,
			'source_vision_frames': source_vision_frames,
			'source_audio_frame': source_audio_frame,
			'source_voice_frame': source_voice_frame,
			'target_vision_frame': target_vision_frame[:, :, :3],
			'temp_vision_frame': temp_vision_frame[:, :, :3],
			'temp_vision_mask': temp_vision_mask
		})

	temp_vision_frame = conditional_merge_vision_mask(temp_vision_frame, temp_vision_mask)
	return write_image(temp_frame_path, temp_vision_frame)

def tick(self):
    now = monotonic()
    read_needed, write_needed, readable, remove, close_needed = [], [], [], [], []
    has_ssl = self.ssl_context is not None
    for s, conn in iteritems(self.connection_map):
        if now - conn.last_activity > self.opts.timeout:
            if conn.handle_timeout():
                conn.last_activity = now
            else:
                remove.append((s, conn))
                continue
        wf = conn.wait_for
        if wf is READ or wf is RDWR:
            if wf is RDWR:
                write_needed.append(s)
            if conn.read_buffer.has_data:
                readable.append(s)
            else:
                if has_ssl:
                    conn.drain_ssl_buffer()
                    if conn.ready:
                        (readable if conn.read_buffer.has_data else read_needed).append(s)
                    else:
                        close_needed.append((s, conn))
                else:
                    read_needed.append(s)
        elif wf is WRITE:
            write_needed.append(s)

    for s, conn in remove:
        self.log(f'Closing connection because of extended inactivity: {conn.state_description}')
        self.close(s, conn)

    for x, conn in close_needed:
        self.close(s, conn)

    if readable:
        writable = []
    else:
        try:
            readable, writable, _ = select.select([self.socket.fileno(), self.control_out.fileno()] + read_needed, write_needed, [], self.opts.timeout)
        except ValueError:  # self.socket.fileno() == -1
            self.ready = False
            self.log.error('Listening socket was unexpectedly terminated')
            return
        except OSError as e:
            # select.error has no errno attribute. errno is instead
            # e.args[0]
            if getattr(e, 'errno', e.args[0]) in socket_errors_eintr:
                return
            for s, conn in tuple(iteritems(self.connection_map)):
                try:
                    select.select([s], [], [], 0)
                except OSError as e:
                    if getattr(e, 'errno', e.args[0]) not in socket_errors_eintr:
                        self.close(s, conn)  # Bad socket, discard
            return

    if not self.ready:
        return

    ignore = set()
    for s, conn, event in self.get_actions(readable, writable):
        if s in ignore:
            continue
        try:
            conn.handle_event(event)
            if not conn.ready:
                self.close(s, conn)
        except JobQueueFull:
            self.log.exception(f'Server busy handling request: {conn.state_description}')
            if conn.ready:
                if conn.response_started:
                    self.close(s, conn)
                else:
                    try:
                        conn.report_busy()
                    except Exception:
                        self.close(s, conn)
        except Exception as e:
            ignore.add(s)
            ssl_terminated = getattr(conn, 'ssl_terminated', False)
            if ssl_terminated:
                self.log.warn('Client tried to initiate SSL renegotiation, closing connection')
                self.close(s, conn)
            else:
                self.log.exception(f'Unhandled exception in state: {conn.state_description}')
                if conn.ready:
                    if conn.response_started:
                        self.close(s, conn)
                    else:
                        try:
                            conn.report_unhandled_exception(e, traceback.format_exc())
                        except Exception:
                            self.close(s, conn)
                else:
                    self.log.error(f'Error in SSL handshake, terminating connection: {as_unicode(e)}')
                    self.close(s, conn)

def run(self):
    while True:
        x = self.request_queue.get()
        if x is None:
            break
        job_id, func = x
        self.working = True
        try:
            result = func()
        except Exception:
            self.handle_error(job_id)  # must be a separate function to avoid reference cycles with sys.exc_info()
        else:
            self.result_queue.put((job_id, True, result))
        finally:
            self.working = False
        try:
            self.notify_server()
        except Exception:
            self.log.exception('ServerWorker failed to notify server on job completion')

def stop(self, wait_till):
    for w in self.workers:
        if w.is_alive():
            try:
                w.plugin.stop()
            except Exception:
                self.loop.log.exception('Failed to stop plugin:', self.plugin_name(w.plugin))
    for w in self.workers:
        left = wait_till - monotonic()
        if left > 0:
            w.join(left)
        else:
            break
    self.workers = [w for w in self.workers if w.is_alive()]

