def test_terminal_classes_has_status_code() -> None:
    terminals = set()
    for name in dir(web):
        obj = getattr(web, name)
        if isinstance(obj, type) and issubclass(obj, web.HTTPException):
            terminals.add(obj)

    dup = frozenset(terminals)
    for cls1 in dup:
        for cls2 in dup:
            if cls1 in cls2.__bases__:
                terminals.discard(cls1)

    for cls in terminals:
        assert cls.status_code is not None
    codes = collections.Counter(cls.status_code for cls in terminals)
    assert None not in codes
    assert 1 == codes.most_common(1)[0][1]

class EnsureOctetStream(Message):
    def __init__(self) -> None:
        super().__init__()
        self.set_default_type("application/octet-stream")

    def get_content_type(self) -> Any:
        """Re-implementation from Message

        Returns application/octet-stream in place of plain/text when
        value is wrong.

        The way this class is used guarantees that content-type will
        be present so simplify the checks wrt to the base implementation.
        """
        value = self.get("content-type").lower()

        # Based on the implementation of _splitparam in the standard library
        ctype, sep, _ = value.partition(";")
        if not sep:
            ctype = ctype.strip()
        if ctype.count("/") != 1:
            return self.get_default_type()
        return ctype

async def wshandler(request: web.Request) -> web.WebSocketResponse | web.Response:
    resp = web.WebSocketResponse()
    available = resp.can_prepare(request)
    if not available:
        with open(WS_FILE, "rb") as fp:
            return web.Response(body=fp.read(), content_type="text/html")

    await resp.prepare(request)

    await resp.send_str("Welcome!!!")

    try:
        print("Someone joined.")
        for ws in request.app[sockets]:
            await ws.send_str("Someone joined")
        request.app[sockets].append(resp)

        async for msg in resp:
            if msg.type is web.WSMsgType.TEXT:
                for ws in request.app[sockets]:
                    if ws is not resp:
                        await ws.send_str(msg.data)
            else:
                return resp
        return resp

    finally:
        request.app[sockets].remove(resp)
        print("Someone disconnected.")
        for ws in request.app[sockets]:
            await ws.send_str("Someone disconnected.")

class DestinationSnowflakeCortex(Destination):
    sql_processor: cortex_processor.SnowflakeCortexSqlProcessor

    def _init_sql_processor(
        self, config: ConfigModel, configured_catalog: Optional[ConfiguredAirbyteCatalog] = None
    ):
        sql_config_params: dict[str, Any] = {
            "host": config.indexing.host,
            "role": config.indexing.role,
            "warehouse": config.indexing.warehouse,
            "database": config.indexing.database,
            "schema_name": config.indexing.default_schema,
            "username": config.indexing.username,
        }

        if isinstance(config.indexing.credentials, PasswordBasedAuthorizationModel):
            sql_config_params["password"] = SecretString(config.indexing.credentials.password)
        elif isinstance(config.indexing.credentials, KeyPairAuthorizationModel):
            sql_config_params["private_key"] = SecretString(config.indexing.credentials.private_key)
            if config.indexing.credentials.private_key_passphrase:
                sql_config_params["private_key_passphrase"] = SecretString(
                    config.indexing.credentials.private_key_passphrase
                )

        self.sql_processor = cortex_processor.SnowflakeCortexSqlProcessor(
            sql_config=cortex_processor.SnowflakeCortexConfig(**sql_config_params),
            splitter_config=config.processing,
            embedder_config=config.embedding,  # type: ignore [arg-type]  # No common base class
            catalog_provider=CatalogProvider(configured_catalog),
            temp_dir=Path(tempfile.mkdtemp()),
            temp_file_cleanup=True,
        )

    def write(
        self,
        config: Mapping[str, Any],
        configured_catalog: ConfiguredAirbyteCatalog,
        input_messages: Iterable[AirbyteMessage],
    ) -> Iterable[AirbyteMessage]:
        parsed_config = ConfigModel.parse_obj(config)
        self._init_sql_processor(config=parsed_config, configured_catalog=configured_catalog)
        yield from self.sql_processor.process_airbyte_messages_as_generator(
            messages=input_messages,
            write_strategy=WriteStrategy.AUTO,
            # TODO: Ensure this setting is covered, then delete the commented-out line:
            # omit_raw_text=parsed_config.omit_raw_text,
        )

    def check(self, logger: Logger, config: Mapping[str, Any]) -> AirbyteConnectionStatus:
        _ = logger  # Unused
        try:
            parsed_config = ConfigModel.parse_obj(config)
            self._init_sql_processor(config=parsed_config)
            self.sql_processor.sql_config.connect()
            return AirbyteConnectionStatus(status=Status.SUCCEEDED)
        except Exception as e:
            return AirbyteConnectionStatus(
                status=Status.FAILED, message=f"An exception occurred: {repr(e)}"
            )

    def spec(self, *args: Any, **kwargs: Any) -> ConnectorSpecification:
        return ConnectorSpecification(
            documentationUrl="https://docs.airbyte.com/integrations/destinations/snowflake-cortex",
            supportsIncremental=True,
            supported_destination_sync_modes=[
                DestinationSyncMode.overwrite,
                DestinationSyncMode.append,
                DestinationSyncMode.append_dedup,
            ],
            connectionSpecification=ConfigModel.schema(),  # type: ignore[attr-defined]
        )

class OpenAIAudio(Audio):
    """OpenAI Audio functionality container."""

    def __init__(self, client):
        super().__init__()
        self.transcriptions = self.Transcriptions(client)

    class Transcriptions(Audio.Transcription):
        """OpenAI Audio Transcriptions functionality."""

        def __init__(self, client):
            self.client = client

        def create(
            self,
            model: str,
            file: Union[str, BinaryIO],
            options: Optional[TranscriptionOptions] = None,
            **kwargs,
        ) -> TranscriptionResult:
            """Create audio transcription using OpenAI Whisper API."""
            try:
                # Determine parameters to use
                if options is not None:
                    api_params = ParameterMapper.map_to_openai(options)
                else:
                    api_params = kwargs

                # Use the model name directly (client already extracted it)
                model_name = model

                # Handle timestamp_granularities requirement
                if "timestamp_granularities" in api_params:
                    # OpenAI requires verbose_json format for timestamp_granularities
                    api_params["response_format"] = "verbose_json"

                # Handle file input
                if isinstance(file, str):
                    with open(file, "rb") as audio_file:
                        response = self.client.audio.transcriptions.create(
                            file=audio_file, model=model_name, **api_params
                        )
                else:
                    response = self.client.audio.transcriptions.create(
                        file=file, model=model_name, **api_params
                    )

                return self._parse_openai_response(response)

            except Exception as e:
                raise ASRError(f"OpenAI transcription error: {e}")

        async def create_stream_output(
            self,
            model: str,
            file: Union[str, BinaryIO],
            options: Optional[TranscriptionOptions] = None,
            **kwargs,
        ) -> AsyncGenerator[StreamingTranscriptionChunk, None]:
            """Create output streaming audio transcription using OpenAI Whisper API."""
            try:
                # Determine parameters to use
                if options is not None:
                    api_params = ParameterMapper.map_to_openai(options)
                else:
                    api_params = kwargs

                # Use the model name directly (client already extracted it)
                model_name = model

                # Try real streaming with OpenAI API
                api_params["stream"] = True

                # Handle timestamp_granularities requirement
                if "timestamp_granularities" in api_params:
                    # OpenAI requires verbose_json format for timestamp_granularities
                    if "response_format" in api_params and api_params["response_format"] != "verbose_json":
                        raise ASRError(
                            f"OpenAI timestamp_granularities requires response_format='verbose_json', "
                            f"but got '{api_params['response_format']}'. "
                            f"Either remove timestamp_granularities or use response_format='verbose_json'. "
                            f"Note: Model '{model_name}' may not support verbose_json format."
                        )
                    else:
                        api_params["response_format"] = "verbose_json"

                try:

                    if isinstance(file, str):
                        with open(file, "rb") as audio_file:
                            response_stream = self.client.audio.transcriptions.create(
                                file=audio_file, model=model_name, **api_params
                            )
                    else:
                        response_stream = self.client.audio.transcriptions.create(
                            file=file, model=model_name, **api_params
                        )

                    # Process streaming response - handle new event types
                    for event in response_stream:
                        # Handle TranscriptionTextDeltaEvent (incremental text)
                        if hasattr(event, 'type') and event.type == 'transcript.text.delta':
                            if hasattr(event, 'delta') and event.delta:
                                yield StreamingTranscriptionChunk(
                                    text=event.delta,
                                    is_final=False,  # Delta events are interim
                                    confidence=getattr(event, "confidence", None),
                                )
                        # Handle TranscriptionTextDoneEvent (final complete text)
                        elif hasattr(event, 'type') and event.type == 'transcript.text.done':
                            if hasattr(event, 'text') and event.text:
                                yield StreamingTranscriptionChunk(
                                    text=event.text,
                                    is_final=True,  # Done event is final
                                    confidence=getattr(event, "confidence", None),
                                )

                except Exception as stream_error:
                    raise ASRError(f"OpenAI streaming transcription error: {stream_error}")

            except Exception as e:
                raise ASRError(f"OpenAI streaming transcription error: {e}")

        def _parse_openai_response(self, response) -> TranscriptionResult:
            """Parse OpenAI API response into TranscriptionResult."""
            text = response.text if hasattr(response, "text") else ""
            language = getattr(response, "language", "unknown")

            # Parse segments if available
            segments = []
            if hasattr(response, "segments") and response.segments:
                for seg in response.segments:
                    words = []
                    if hasattr(seg, "words") and seg.words:
                        for word in seg.words:
                            words.append(
                                Word(
                                    word=word.word,
                                    start=word.start,
                                    end=word.end,
                                    confidence=getattr(word, "confidence", None),
                                )
                            )

                    segments.append(
                        Segment(
                            id=getattr(seg, "id", 0),
                            seek=getattr(seg, "seek", 0),
                            text=seg.text,
                            start=seg.start,
                            end=seg.end,
                            words=words,
                            confidence=getattr(seg, "avg_logprob", None),
                        )
                    )

            return TranscriptionResult(
                text=text,
                language=language,
                confidence=getattr(response, "confidence", None),
                segments=segments,
            )

def convert_assistant_role_message(message: Dict[str, Any]) -> Content:
    """Convert assistant messages to Google Vertex AI format."""
    if "tool_calls" in message and message["tool_calls"]:
        # Handle function calls
        tool_call = message["tool_calls"][
            0
        ]  # Assuming single function call for now
        function_call = tool_call["function"]

        # Create a Part from the function call
        parts = [
            Part.from_dict(
                {
                    "function_call": {
                        "name": function_call["name"],
                        # "arguments": json.loads(function_call["arguments"])
                    }
                }
            )
        ]
        # return Content(role="function", parts=parts)
    else:
        # Handle regular text messages
        parts = [Part.from_text(message["content"])]
        # return Content(role="model", parts=parts)

    return Content(role="model", parts=parts)

def convert_request(messages: List[Dict[str, Any]]) -> List[Content]:
    """Convert messages to Google Vertex AI format."""
    # Convert all messages to dicts if they're Message objects
    messages = [
        message.model_dump() if hasattr(message, "model_dump") else message
        for message in messages
    ]

    formatted_messages = []
    for message in messages:
        if message["role"] == "tool":
            vertex_message = GoogleMessageConverter.convert_tool_role_message(
                message
            )
            if vertex_message:
                formatted_messages.append(vertex_message)
        elif message["role"] == "assistant":
            formatted_messages.append(
                GoogleMessageConverter.convert_assistant_role_message(message)
            )
        else:  # user or system role
            formatted_messages.append(
                GoogleMessageConverter.convert_user_role_message(message)
            )

    return formatted_messages

def convert_response(response) -> ChatCompletionResponse:
    """Normalize the response from Vertex AI to match OpenAI's response format."""
    openai_response = ChatCompletionResponse()

    if ENABLE_DEBUG_MESSAGES:
        print("Dumping the response")
        pprint.pprint(response)

    # TODO: We need to go through each part, because function call may not be the first part.
    #       Currently, we are only handling the first part, but this is not enough.
    #
    # This is a valid response:
    # candidates {
    #   content {
    #     role: "model"
    #     parts {
    #       text: "The current temperature in San Francisco is 72 degrees Celsius. \n\n"
    #     }
    #     parts {
    #       function_call {
    #         name: "is_it_raining"
    #         args {
    #           fields {
    #             key: "location"
    #             value {
    #               string_value: "San Francisco"
    #             }
    #           }
    #         }
    #       }
    #     }
    #   }
    #   finish_reason: STOP

    # Check if the response contains function calls
    # Note: Just checking if the function_call attribute exists is not enough,
    #       it is important to check if the function_call is not None.
    if (
        hasattr(response.candidates[0].content.parts[0], "function_call")
        and response.candidates[0].content.parts[0].function_call
    ):
        function_call = response.candidates[0].content.parts[0].function_call

        # args is a MapComposite.
        # Convert the MapComposite to a dictionary
        args_dict = {}
        # Another way to try is: args_dict = dict(function_call.args)
        for key, value in function_call.args.items():
            args_dict[key] = value
        if ENABLE_DEBUG_MESSAGES:
            print("Dumping the args_dict")
            pprint.pprint(args_dict)

        openai_response.choices[0].message = {
            "role": "assistant",
            "content": None,
            "tool_calls": [
                {
                    "type": "function",
                    "id": f"call_{hash(function_call.name)}",  # Generate a unique ID
                    "function": {
                        "name": function_call.name,
                        "arguments": json.dumps(args_dict),
                    },
                }
            ],
            "refusal": None,
        }
        openai_response.choices[0].message = Message(
            **openai_response.choices[0].message
        )
        openai_response.choices[0].finish_reason = "tool_calls"
    else:
        # Handle regular text response
        openai_response.choices[0].message.content = (
            response.candidates[0].content.parts[0].text
        )
        openai_response.choices[0].finish_reason = "stop"

    return openai_response

def chat_completions_create(self, model, messages, **kwargs):
    """Request chat completions from the Google AI API.

    Args:
    ----
        model (str): Identifies the specific provider/model to use.
        messages (list of dict): A list of message objects in chat history.
        kwargs (dict): Optional arguments for the Google AI API.

    Returns:
    -------
        The ChatCompletionResponse with the completion result.

    """

    # Set the temperature if provided, otherwise use the default
    temperature = kwargs.get("temperature", DEFAULT_TEMPERATURE)

    # Convert messages to Vertex AI format
    message_history = self.transformer.convert_request(messages)

    # Handle tools if provided
    tools = None
    if "tools" in kwargs:
        tools = [
            Tool(
                function_declarations=[
                    FunctionDeclaration(
                        name=tool["function"]["name"],
                        description=tool["function"].get("description", ""),
                        parameters={
                            "type": "object",
                            "properties": {
                                param_name: {
                                    "type": param_info.get("type", "string"),
                                    "description": param_info.get(
                                        "description", ""
                                    ),
                                    **(
                                        {"enum": param_info["enum"]}
                                        if "enum" in param_info
                                        else {}
                                    ),
                                }
                                for param_name, param_info in tool["function"][
                                    "parameters"
                                ]["properties"].items()
                            },
                            "required": tool["function"]["parameters"].get(
                                "required", []
                            ),
                        },
                    )
                    for tool in kwargs["tools"]
                ]
            )
        ]

    # Create the GenerativeModel
    model = GenerativeModel(
        model,
        generation_config=GenerationConfig(temperature=temperature),
        tools=tools,
    )

    if ENABLE_DEBUG_MESSAGES:
        print("Dumping the message_history")
        pprint.pprint(message_history)

    # Start chat and get response
    chat = model.start_chat(history=message_history[:-1])
    last_message = message_history[-1]

    # If the last message is a function response, send the Part object directly
    # Otherwise, send just the text content
    message_to_send = (
        Content(role="function", parts=[last_message])
        if isinstance(last_message, Part)
        else last_message.parts[0].text
    )
    # response = chat.send_message(message_to_send)
    response = chat.send_message(message_to_send)

    # Convert and return the response
    return self.transformer.convert_response(response)

class GoogleAudio(Audio):
    """Google Audio functionality container."""

    def __init__(self, provider):
        super().__init__()
        self.provider = provider
        self.transcriptions = self.Transcriptions(provider)

    class Transcriptions(Audio.Transcription):
        """Google Audio Transcriptions functionality."""

        def __init__(self, provider):
