class _Properties(UserDict):
    __PROPERTIES_ATTRIBUTE_NAME = "properties"

    def __init__(self, entity_owner, **kwargs):
        super().__init__(**kwargs)
        self._entity_owner = entity_owner
        self._pending_changes = {}
        self._pending_deletions = set()

    def __setitem__(self, key, value):
        if key == "path":
            value = _normalize_path(value)
        super(_Properties, self).__setitem__(key, value)

        if hasattr(self, "_entity_owner"):
            event = _make_event(
                self._entity_owner,
                EventOperation.UPDATE,
                attribute_name=self.__PROPERTIES_ATTRIBUTE_NAME,
                attribute_value=value,
            )
            if not self._entity_owner._is_in_context:
                self._set_entity_owner(self._entity_owner)
                Notifier.publish(event)
            else:
                if key in self._pending_deletions:
                    self._pending_deletions.remove(key)
                self._pending_changes[key] = value
                self._entity_owner._in_context_attributes_changed_collector.append(event)

    def __getitem__(self, key):
        return _tpl._replace_templates(super(_Properties, self).__getitem__(key))

    def __delitem__(self, key):
        super(_Properties, self).__delitem__(key)

        if hasattr(self, "_entity_owner"):
            event = _make_event(
                self._entity_owner,
                EventOperation.UPDATE,
                attribute_name=self.__PROPERTIES_ATTRIBUTE_NAME,
                attribute_value=None,
            )
            if not self._entity_owner._is_in_context:
                self._set_entity_owner(self._entity_owner)
                Notifier.publish(event)
            else:
                self._pending_changes.pop(key, None)
                self._pending_deletions.add(key)
                self._entity_owner._in_context_attributes_changed_collector.append(event)

    def _set_entity_owner(self, entity_owner):
        from ... import core as tp

        tp.set(entity_owner)

class _ListAttributes(UserList):
    def __init__(self, parent, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._parent = parent

    def __add_iterable(self, iterable):
        for i in iterable:
            super(_ListAttributes, self).append(i)

    def __set_self(self):
        from ... import core as tp

        if hasattr(self, "_parent"):
            tp.set(self._parent)

    def __add__(self, value):
        if hasattr(value, "__iter__"):
            self.__add_iterable(value)
        else:
            self.append(value)
        return self

    def extend(self, value) -> None:
        super(_ListAttributes, self).extend(value)
        self.__set_self()

    def append(self, value) -> None:
        super(_ListAttributes, self).append(value)
        self.__set_self()

    def remove(self, value):
        super(_ListAttributes, self).remove(value)
        self.__set_self()

    def clear(self) -> None:
        super(_ListAttributes, self).clear()
        self.__set_self()

