class FlaskRestfulPlugin(FlaskPlugin):
    """Small plugin override to handle flask-restful resources"""

    @staticmethod
    def _rule_for_view(view, app=None):
        view_funcs = app.view_functions
        endpoint = None

        for ept, view_func in view_funcs.items():
            if hasattr(view_func, "view_class"):
                view_func = view_func.view_class

            if view_func == view:
                endpoint = ept

        if not endpoint:
            raise APISpecError("Could not find endpoint for view {0}".format(view))

        # WARNING: Assume 1 rule per view function for now
        return app.url_map._rules_by_endpoint[endpoint][0]

class APISpecExt:
    """Very simple and small extension to use apispec with this API as a flask extension"""

    def __init__(self, app=None, **kwargs):
        self.spec = None

        if app is not None:
            self.init_app(app, **kwargs)

    def init_app(self, app, **kwargs):
        app.config.setdefault("APISPEC_TITLE", "Taipy Rest")
        app.config.setdefault("APISPEC_VERSION", "1.0.0")
        app.config.setdefault("OPENAPI_VERSION", "3.0.2")
        app.config.setdefault("SWAGGER_JSON_URL", "/swagger.json")
        app.config.setdefault("SWAGGER_UI_URL", "/swagger-ui")
        app.config.setdefault("OPENAPI_YAML_URL", "/openapi.yaml")
        app.config.setdefault("REDOC_UI_URL", "/redoc-ui")
        app.config.setdefault("SWAGGER_URL_PREFIX", None)

        self.spec = APISpec(
            title=app.config["APISPEC_TITLE"],
            version=app.config["APISPEC_VERSION"],
            openapi_version=app.config["OPENAPI_VERSION"],
            plugins=[MarshmallowPlugin(), FlaskRestfulPlugin()],
            **kwargs,
        )

        blueprint = Blueprint(
            "swagger",
            __name__,
            template_folder="./templates",
            url_prefix=app.config["SWAGGER_URL_PREFIX"],
        )

        blueprint.add_url_rule(app.config["SWAGGER_JSON_URL"], "swagger_json", self.swagger_json)
        blueprint.add_url_rule(app.config["SWAGGER_UI_URL"], "swagger_ui", self.swagger_ui)
        blueprint.add_url_rule(app.config["OPENAPI_YAML_URL"], "openapi_yaml", self.openapi_yaml)
        blueprint.add_url_rule(app.config["REDOC_UI_URL"], "redoc_ui", self.redoc_ui)

        app.register_blueprint(blueprint)

    def swagger_json(self):
        return jsonify(self.spec.to_dict())

    def swagger_ui(self):
        return render_template("swagger.j2")

    def openapi_yaml(self):
        # Manually inject ReDoc's Authentication legend, then remove it
        self.spec.tag(
            {
                "name": "authentication",
                "x-displayName": "Authentication",
                "description": "<SecurityDefinitions />",
            }
        )
        redoc_spec = self.spec.to_yaml()
        self.spec._tags.pop(0)
        return redoc_spec

    def redoc_ui(self):
        return render_template("redoc.j2")

def check_eval_packing(cls, data):
    # TODO also should check test_datasets and val_set_size as we can skip
    # if there are no eval datasets/splits
    if (
        data.get("sample_packing")
        and data.get("eval_table_size")
        and data.get("eval_sample_packing") is not False
    ):
        raise ValueError(
            "eval_table_size and eval_sample_packing are not supported together with sample_packing. Please set 'eval_sample_packing' to false."
        )
    if (
        data.get("sample_packing")
        and data.get("eval_sample_packing") is None
        and not data.get("eval_table_size")
    ):
        LOG.info(
            "explicitly setting `eval_sample_packing` to match `sample_packing`",
            main_process_only=True,
        )
        data["eval_sample_packing"] = True

    if (
        data.get("sample_packing")
        and data.get("eval_sample_packing") is False
        and data.get("remove_unused_columns") is None
    ):
        LOG.info(
            "setting `remove_unused_columns: false` for when sample_packing and eval_sample_packing don't match"
        )
        data["remove_unused_columns"] = False

    return data

def _extract_type_from_source(
    self, model_class: type[BaseModel], field_name: str
) -> str:
    """Extract the actual type annotation text from source code."""
    try:
        source = inspect.getsource(model_class)
        tree = ast.parse(source)
    except (OSError, TypeError):
        return "unknown"

    # Find the class definition
    class_node = None
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef) and node.name == model_class.__name__:
            class_node = node
            break

    if not class_node:
        return "unknown"

    # Find the field assignment
    for node in class_node.body:
        if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            if node.target.id == field_name and node.annotation:
                # Convert the AST annotation back to source text
                return ast.unparse(node.annotation)

    return "unknown"
    """Format field type information in a readable way."""
    # Handle fallback case where we only have basic info
    if field_info.get("type") == "unknown":
        return "unknown"

    if "anyOf" in field_info:
        types = []
        is_optional = False

        for option in field_info["anyOf"]:
            if option.get("type") == "null":
                is_optional = True
            elif option.get("type"):
                types.append(option["type"])
            elif "$ref" in option:
                ref_name = option["$ref"].split("/")[-1]
                types.append(ref_name)

        type_str = " | ".join(types) if types else "unknown"
        return f"{type_str} | None" if is_optional else type_str

    field_type = field_info.get("type", "unknown")

    if field_type == "array":
        items = field_info.get("items", {})
        if items.get("type"):
            item_type = items["type"]
        elif "$ref" in items:
            item_type = items["$ref"].split("/")[-1]
        else:
            item_type = "unknown"
        return f"list[{item_type}]"

    if field_type == "object":
        return "dict"

    return field_type

