def generate_qmd(
    self, model_class: type[BaseModel], title: str | None = None
) -> str:
    """Auto-generate config reference documentation."""

    if title is None:
        title = f"{model_class.__name__} Reference"

    # Try to get JSON schema, with fallback for serialization issues
    try:
        schema = model_class.model_json_schema()
        properties = schema.get("properties", {})
        required = schema.get("required", [])
    except Exception as e:
        print(
            f"Warning: Could not generate JSON schema ({e}). Using model fields instead."
        )
        # Fallback: use model fields directly
        properties = {}
        required = []
        for field_name, field_info in model_class.model_fields.items():
            # Extract description from json_schema_extra or field info
            description = ""
            if (
                hasattr(field_info, "json_schema_extra")
                and field_info.json_schema_extra
            ):
                description = field_info.json_schema_extra.get("description", "")
            elif hasattr(field_info, "description") and field_info.description:
                description = field_info.description

            # Get default value
            default_val = None
            if hasattr(field_info, "default") and field_info.default is not None:
                # Handle special Pydantic default markers
                if str(field_info.default) != "PydanticUndefined":
                    default_val = field_info.default

            properties[field_name] = {
                "type": "unknown",
                "description": description,
                "default": default_val,
            }

            if field_info.is_required():
                required.append(field_name)

    # Extract field groups from source code
    field_groups = self._extract_field_groups_from_source(model_class)

    # Start building QMD content
    qmd_lines = [
        "---",
        f"title: {title}",
        "description: A complete list of all configuration options.",
        "---",
        "",
    ]

    # Generate one big code block with all fields
    qmd_lines.append("```yaml")

    for i, group in enumerate(field_groups):
        if not group["fields"]:
            continue

        # Add blank line between groups (except before first group)
        if i > 0:
            qmd_lines.append("")

        # Process fields in the order they appear in source
        for field_name in group["fields"]:
            if field_name not in properties:
                continue

            field_info = properties[field_name]
            field_type = self._extract_type_from_source(model_class, field_name)
            is_required = field_name in required

            description = field_info.get("description", "")
            default = field_info.get("default")

            # Add wrapped comment for description
            if description:
                wrapped_lines = self._wrap_comment(description)
                qmd_lines.extend(wrapped_lines)

            line = f"{field_name}: {field_type}"
            if default is not None:
                line += f" = {default}"
            if is_required:
                line += " (required)"
            qmd_lines.append(line)

    qmd_lines.append("```")

    return "\n".join(qmd_lines)

#!/usr/bin/env python3
"""
Enhanced Quarto documentation generator from Pydantic models.
Uses source code structure to automatically group fields.
"""

import ast
import inspect
import textwrap
from typing import Any

import yaml
from pydantic import BaseModel

from axolotl.utils.schemas.config import AxolotlInputConfig


class QuartoGenerator:
    """Generate Quarto documentation from Pydantic models."""

    def _wrap_comment(self, text: str, width: int = 88) -> list[str]:
        """Wrap a comment to specified width, accounting for '# ' prefix."""
        if not text.strip():
            return ["#"]

        # Account for "# " prefix (2 characters)
        content_width = width - 2
        wrapped_lines = textwrap.wrap(text, width=content_width)
        return [f"# {line}" for line in wrapped_lines]

    def _extract_type_from_source(
        self, model_class: type[BaseModel], field_name: str
    ) -> str:
        """Extract the actual type annotation text from source code."""
        try:
            source = inspect.getsource(model_class)
            tree = ast.parse(source)
        except (OSError, TypeError):
            return "unknown"

        # Find the class definition
        class_node = None
        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef) and node.name == model_class.__name__:
                class_node = node
                break

        if not class_node:
            return "unknown"

        # Find the field assignment
        for node in class_node.body:
            if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
                if node.target.id == field_name and node.annotation:
                    # Convert the AST annotation back to source text
                    return ast.unparse(node.annotation)

        return "unknown"
        """Format field type information in a readable way."""
        # Handle fallback case where we only have basic info
        if field_info.get("type") == "unknown":
            return "unknown"

        if "anyOf" in field_info:
            types = []
            is_optional = False

            for option in field_info["anyOf"]:
                if option.get("type") == "null":
                    is_optional = True
                elif option.get("type"):
                    types.append(option["type"])
                elif "$ref" in option:
                    ref_name = option["$ref"].split("/")[-1]
                    types.append(ref_name)

            type_str = " | ".join(types) if types else "unknown"
            return f"{type_str} | None" if is_optional else type_str

        field_type = field_info.get("type", "unknown")

        if field_type == "array":
            items = field_info.get("items", {})
            if items.get("type"):
                item_type = items["type"]
            elif "$ref" in items:
                item_type = items["$ref"].split("/")[-1]
            else:
                item_type = "unknown"
            return f"list[{item_type}]"

        if field_type == "object":
            return "dict"

        return field_type

    def _extract_field_groups_from_source(
        self, model_class: type[BaseModel]
    ) -> list[dict]:
        """Extract field groups from source code based on blank lines and comments."""
        try:
            source = inspect.getsource(model_class)
            tree = ast.parse(source)
        except (OSError, TypeError):
            # Fallback if we can't get source code
            return [
                {
                    "title": "Configuration Options",
                    "fields": list(model_class.model_fields.keys()),
                }
            ]

        groups = []
        current_group_fields = []
        current_group_title = None
        current_group_comment = None

        # Find the class definition
        class_node = None
        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef) and node.name == model_class.__name__:
                class_node = node
                break

        if not class_node:
            return [
                {
                    "title": "Configuration Options",
                    "fields": list(model_class.model_fields.keys()),
                }
            ]

        # Parse the source lines to detect groupings
        source_lines = source.split("\n")

        # Find assignments that correspond to model fields
        field_assignments = []
        for node in class_node.body:
            if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
                field_name = node.target.id
                if field_name in model_class.model_fields:
                    field_assignments.append(
                        {
                            "name": field_name,
                            "lineno": node.lineno,
                            "end_lineno": getattr(node, "end_lineno", node.lineno),
                        }
                    )

        if not field_assignments:
            return [
                {
                    "title": "Configuration Options",
                    "fields": list(model_class.model_fields.keys()),
                }
            ]

        # Sort by line number
        field_assignments.sort(key=lambda x: x["lineno"])

        # Group fields based on blank lines and comments
        for i, field_info in enumerate(field_assignments):
            field_name = field_info["name"]
            current_line = field_info["lineno"]

            # Check if this starts a new group (blank line before or significant gap)
            is_new_group = False

            if i == 0:
                is_new_group = True
            else:
                prev_end_line = field_assignments[i - 1]["end_lineno"]

                # Check for blank lines or comments between fields
                lines_between = source_lines[prev_end_line : current_line - 1]
                has_blank_line = any(line.strip() == "" for line in lines_between)
                has_comment = any(
                    line.strip().startswith("#") for line in lines_between
                )

                # Start new group if there's a blank line or comment, or significant gap
                if has_blank_line or has_comment or (current_line - prev_end_line > 3):
                    is_new_group = True

            if is_new_group and current_group_fields:
                # Save the previous group
                title = current_group_title or f"Group {len(groups) + 1}"
                groups.append(
                    {
                        "title": title,
                        "fields": current_group_fields.copy(),
                        "description": current_group_comment,
                    }
                )
                current_group_fields = []
                current_group_title = None
                current_group_comment = None

            # Look for a comment that might serve as a group title
            if is_new_group:
                # Check lines before this field for comments
                start_check = max(0, current_line - 5)
                for line_idx in range(start_check, current_line - 1):
                    if line_idx < len(source_lines):
                        line = source_lines[line_idx].strip()
                        if line.startswith("#") and not line.startswith("# "):
                            # This might be a section comment
                            comment_text = line.lstrip("#").strip()
                            if len(
                                comment_text
                            ) > 0 and not comment_text.lower().startswith(
                                ("todo", "fixme", "note")
                            ):
                                current_group_title = comment_text.title()
                                current_group_comment = comment_text

            current_group_fields.append(field_name)

        # Add the final group
        if current_group_fields:
            title = current_group_title or f"Group {len(groups) + 1}"
            groups.append(
                {
                    "title": title,
                    "fields": current_group_fields,
                    "description": current_group_comment,
                }
            )

        # If no groups were created, create a default one
        if not groups:
            groups.append(
                {
                    "title": "Configuration Options",
                    "fields": list(model_class.model_fields.keys()),
                }
            )

        return groups

    def _get_yaml_example(
        self, field_name: str, field_info: dict[str, Any]
    ) -> str | None:
        """Generate a YAML example for the field."""
        default = field_info.get("default")

        # Common examples based on field names
        examples = {
            "base_model": "./llama-7b-hf",
            "model_type": "AutoModelForCausalLM",
            "tokenizer_type": "AutoTokenizer",
            "sequence_len": 2048,
            "micro_batch_size": 2,
            "gradient_accumulation_steps": 1,
            "num_epochs": 4,
            "learning_rate": 0.00003,
            "warmup_steps": 100,
            "lora_r": 8,
            "lora_alpha": 16,
            "lora_dropout": 0.05,
            "lora_target_modules": ["q_proj", "v_proj"],
            "load_in_8bit": True,
            "bf16": True,
            "flash_attention": True,
            "gradient_checkpointing": True,
            "output_dir": "./completed-model",
            "wandb_project": "my-finetuning-project",
        }

        if field_name in examples:
            return yaml.dump(
                {field_name: examples[field_name]}, default_style=None
            ).strip()

        if default is not None:
            return yaml.dump({field_name: default}, default_style=None).strip()

        return None

    def generate_qmd(
        self, model_class: type[BaseModel], title: str | None = None
    ) -> str:
        """Auto-generate config reference documentation."""

        if title is None:
            title = f"{model_class.__name__} Reference"

        # Try to get JSON schema, with fallback for serialization issues
        try:
            schema = model_class.model_json_schema()
            properties = schema.get("properties", {})
            required = schema.get("required", [])
        except Exception as e:
            print(
                f"Warning: Could not generate JSON schema ({e}). Using model fields instead."
            )
            # Fallback: use model fields directly
            properties = {}
            required = []
            for field_name, field_info in model_class.model_fields.items():
                # Extract description from json_schema_extra or field info
                description = ""
                if (
                    hasattr(field_info, "json_schema_extra")
                    and field_info.json_schema_extra
                ):
                    description = field_info.json_schema_extra.get("description", "")
                elif hasattr(field_info, "description") and field_info.description:
                    description = field_info.description

                # Get default value
                default_val = None
                if hasattr(field_info, "default") and field_info.default is not None:
                    # Handle special Pydantic default markers
                    if str(field_info.default) != "PydanticUndefined":
                        default_val = field_info.default

                properties[field_name] = {
                    "type": "unknown",
                    "description": description,
                    "default": default_val,
                }

                if field_info.is_required():
                    required.append(field_name)

        # Extract field groups from source code
        field_groups = self._extract_field_groups_from_source(model_class)

        # Start building QMD content
        qmd_lines = [
            "---",
            f"title: {title}",
            "description: A complete list of all configuration options.",
            "---",
            "",
        ]

        # Generate one big code block with all fields
        qmd_lines.append("```yaml")

        for i, group in enumerate(field_groups):
            if not group["fields"]:
                continue

            # Add blank line between groups (except before first group)
            if i > 0:
                qmd_lines.append("")

            # Process fields in the order they appear in source
            for field_name in group["fields"]:
                if field_name not in properties:
                    continue

                field_info = properties[field_name]
                field_type = self._extract_type_from_source(model_class, field_name)
                is_required = field_name in required

                description = field_info.get("description", "")
                default = field_info.get("default")

                # Add wrapped comment for description
                if description:
                    wrapped_lines = self._wrap_comment(description)
                    qmd_lines.extend(wrapped_lines)

                line = f"{field_name}: {field_type}"
                if default is not None:
                    line += f" = {default}"
                if is_required:
                    line += " (required)"
                qmd_lines.append(line)

        qmd_lines.append("```")

        return "\n".join(qmd_lines)


# Usage example
def main():
    """Example usage of the enhanced generator."""
    generator = QuartoGenerator()

    print("Generating config reference content...")
    qmd_content = generator.generate_qmd(AxolotlInputConfig, "Config Reference")

    print("Writing to file...")
    with open("docs/config-reference.qmd", "w", encoding="utf-8") as f:
        f.write(qmd_content)
    print("Done!")


if __name__ == "__main__":
    main()

"""data handling helpers"""

import functools
import hashlib
import time
from typing import Optional
from enum import Enum

import huggingface_hub
import numpy as np
import requests
from datasets import Dataset, IterableDataset

from axolotl.utils.dict import DictDefault
from axolotl.utils.logging import get_logger
from axolotl.utils.samplers.utils import get_dataset_lengths
from axolotl.utils.trainer import drop_long_seq

LOG = get_logger(__name__)


class RetryStrategy(Enum):
    """
    Enum for retry strategies.
    """

    CONSTANT = 1
    LINEAR = 2
    EXPONENTIAL = 3


def retry_on_request_exceptions(
    max_retries=3, delay=1, retry_strategy: RetryStrategy = RetryStrategy.LINEAR
):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):  # pylint: disable=inconsistent-return-statements
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except (
                    requests.exceptions.ReadTimeout,
                    requests.exceptions.ConnectionError,
                    huggingface_hub.errors.HfHubHTTPError,
                ) as exc:
                    if attempt < max_retries - 1:
                        if retry_strategy == RetryStrategy.EXPONENTIAL:
                            step_delay = delay * 2**attempt
                        elif retry_strategy == RetryStrategy.LINEAR:
                            step_delay = delay * (attempt + 1)
                        else:
                            step_delay = delay  # Use constant delay.
                        time.sleep(step_delay)
                    else:
                        raise exc

        return wrapper

    return decorator


def md5(to_hash: str, encoding: str = "utf-8") -> str:
    try:
        return hashlib.md5(to_hash.encode(encoding), usedforsecurity=False).hexdigest()
    except TypeError:
        return hashlib.md5(to_hash.encode(encoding)).hexdigest()  # nosec


def sha256(to_hash: str, encoding: str = "utf-8") -> str:
    return hashlib.sha256(to_hash.encode(encoding)).hexdigest()


def compute_row_hash(example):
    return {"row_hash": sha256(str(example))}


def deduplicate_dataset(
    dataset: Dataset,
    other_dataset: Dataset = None,
    num_proc: Optional[int] = None,
) -> Dataset:
    hashes, other_hashes, seen_hashes, unique_indices = [], set(), set(), set()

    if dataset is not None:
        hashed = dataset.map(
            compute_row_hash,
            num_proc=num_proc,
        )
        hashes = hashed["row_hash"]

    if other_dataset is not None:
        other_hashed = other_dataset.map(
            compute_row_hash,
            num_proc=num_proc,
        )
        other_hashes = set(other_hashed["row_hash"])

    for idx, row_hash in enumerate(hashes):
        if row_hash in seen_hashes or row_hash in other_hashes:
            continue
        seen_hashes.add(row_hash)
        unique_indices.add(idx)

    return dataset.select(unique_indices)


def deduplicate_and_log_datasets(
    *,
    train_dataset: Dataset = None,
    eval_dataset: Dataset = None,
    dataset: Dataset = None,
    num_proc: Optional[int] = None,
) -> tuple[Dataset, Dataset, Dataset]:
    """
    Deduplicates train, eval, and an optional dataset if provided, logging original and new sizes.

    Returns:
        tuple: Deduplicated train, eval, and additional datasets.
    """
    # Handle cases where datasets are None
    if train_dataset is not None:
        LOG.info(f"Starting deduplication for train dataset. Original size: {len(train_dataset)}")
        train_dataset = deduplicate_dataset(dataset=train_dataset, num_proc=num_proc)
        LOG.info(f"Deduplication complete for train dataset. New size: {len(train_dataset)}")
    else:
        LOG.info("Train dataset is None. Skipping deduplication.")

    if eval_dataset is not None:
        LOG.info(f"Starting deduplication for eval dataset. Original size: {len(eval_dataset)}")
        eval_dataset = deduplicate_dataset(dataset=eval_dataset, other_dataset=train_dataset, num_proc=num_proc)
        LOG.info(f"Deduplication complete for eval dataset. New size: {len(eval_dataset)}")
    else:
        LOG.info("Eval dataset is None. Skipping deduplication.")

    if dataset is not None and (eval_dataset is None and train_dataset is None):
        LOG.info(f"Starting deduplication for combined dataset. Original size: {len(dataset)}")
        dataset = deduplicate_dataset(dataset=dataset, num_proc=num_proc)
        LOG.info(f"Deduplication complete for combined dataset. New size: {len(dataset)}")

    return train_dataset, eval_dataset, dataset


def drop_long_seq_in_dataset(dataset: Dataset, cfg: DictDefault):
    if "input_ids" not in dataset.column_names:
        LOG.warning(
            "Dataset does not contain 'input_ids' column. Skip drop long seq. This is expected for RewardModeling."
        )
        return dataset

    drop_long = functools.partial(
        drop_long_seq,
        sequence_len=cfg.sequence_len,
        min_sequence_len=cfg.min_sample_len,
    )

    try:
        ds_lengths = get_dataset_lengths(dataset, from_arrow=True)
        min_input_len = np.min(ds_lengths)
        LOG.info(f"min_input_len: {min_input_len}")
        max_input_len = np.max(ds_lengths)
        LOG.info(f"max_input_len: {max_input_len}")
    except AttributeError:
        pass

    try:
        prior_len = len(dataset)
    except TypeError:
        # handle iterable datasets case
        prior_len = None

    filter_map_kwargs = {}
    if not isinstance(dataset, IterableDataset):
        filter_map_kwargs["num_proc"] = cfg.dataset_processes
        filter_map_kwargs["load_from_cache_file"] = not cfg.is_preprocess

    drop_long_kwargs = {}
    if filter_map_kwargs:
        drop_long_kwargs["desc"] = "Dropping Long Sequences"

    dataset = dataset.filter(
        drop_long,
        batched=True,
        **filter_map_kwargs,
        **drop_long_kwargs,
    )
    if prior_len:
        dropped = prior_len - len(dataset)
        if dropped:
            LOG.warning(f"Dropped {dropped} long samples from dataset")

    return dataset

def default(
    cfg, dataset_idx=0, **kwargs
):  # pylint: disable=possibly-unused-variable,unused-argument
    ds_cfg = cfg["datasets"][dataset_idx]
    ds_cfg = handle_legacy_message_fields_logic(ds_cfg)

    chat_template_choice, chat_template_jinja = extract_chat_template_args(
        cfg=cfg, ds_cfg=ds_cfg
    )
    field_messages = ds_cfg.get("field_messages", "messages")
    field_chosen = ds_cfg.get("field_chosen", "chosen")
    field_rejected = ds_cfg.get("field_rejected", "rejected")
    message_property_mappings = ds_cfg.get(
        "message_property_mappings",
        {
            "role": "role",
            "content": "content",
        },
    )
    role_map_inv = ds_cfg.get(
        "roles",
        {
            "user": ["user"],
            "assistant": ["assistant"],
            "system": ["system"],
        },
    )
    role_map = {}
    for target, sources in role_map_inv.items():
        for source in sources:
            role_map[source] = target

    def transform_fn(sample, tokenizer=None):
        chat_template_string = get_chat_template(
            user_choice=chat_template_choice,
            jinja_template=chat_template_jinja,
            tokenizer=tokenizer,
        )

        messages = sample[field_messages]
        messages = [
            {
                "role": role_map[m[message_property_mappings["role"]]],
                "content": m[message_property_mappings["content"]],
            }
            for m in messages
        ]
        chosen = {
            "role": role_map[sample[field_chosen][message_property_mappings["role"]]],
            "content": sample[field_chosen][message_property_mappings["content"]],
        }
        rejected = {
            "role": role_map[sample[field_rejected][message_property_mappings["role"]]],
            "content": sample[field_rejected][message_property_mappings["content"]],
        }
        dummy_user_message = {"role": "user", "content": "[[dummy_message]]"}

        result = {}
        result["prompt"] = tokenizer.apply_chat_template(
            messages,
            add_generation_prompt=True,
            chat_template=chat_template_string,
            tokenize=False,
        )

        result["chosen"] = tokenizer.apply_chat_template(
            [dummy_user_message, chosen],
            add_generation_prompt=False,
            chat_template=chat_template_string,
            tokenize=False,
        )
        chosen_strip_index = result["chosen"].find(chosen["content"])
        result["chosen"] = result["chosen"][chosen_strip_index:].rstrip()

        result["rejected"] = tokenizer.apply_chat_template(
            [dummy_user_message, rejected],
            add_generation_prompt=False,
            chat_template=chat_template_string,
            tokenize=False,
        )
        rejected_strip_index = result["rejected"].find(rejected["content"])
        result["rejected"] = result["rejected"][rejected_strip_index:].rstrip()

        return result

    return transform_fn, {"remove_columns":[field_messages]}

