def __init__(self) -> None:
	telemetry_disabled = not CONFIG.ANONYMIZED_TELEMETRY
	self.debug_logging = CONFIG.BROWSER_USE_LOGGING_LEVEL == 'debug'

	if telemetry_disabled:
		self._posthog_client = None
	else:
		logger.info(
			'Anonymized telemetry enabled. See https://docs.browser-use.com/development/telemetry for more information.'
		)
		self._posthog_client = Posthog(
			project_api_key=self.PROJECT_API_KEY,
			host=self.HOST,
			disable_geoip=False,
			enable_exception_autocapture=True,
		)

		# Silence posthog's logging
		if not self.debug_logging:
			posthog_logger = logging.getLogger('posthog')
			posthog_logger.disabled = True

	if self._posthog_client is None:
		logger.debug('Telemetry disabled')

def are_images_identical(img_path1: str, img_path2: str) -> bool:
	"""Check if two images are identical by comparing their content."""
	try:
		with Image.open(img_path1) as img1, Image.open(img_path2) as img2:
			# Convert to same format for comparison
			if img1.mode != img2.mode:
				img1 = img1.convert('RGB')
				img2 = img2.convert('RGB')

			# Compare sizes first (quick check)
			if img1.size != img2.size:
				return False

			# Compare pixel data
			return list(img1.getdata()) == list(img2.getdata())
	except Exception as e:
		logger.warning(f'Failed to compare images {img_path1} and {img_path2}: {e}')
		return False

